const events: GlossaryEntry[] = [
  { slug: 'breakout-session', term: 'Breakout Session', definition: 'A smaller, focused discussion group within a larger event that allows attendees to explore specific topics in depth. Breakout sessions run simultaneously, giving participants choices.', extendedDefinition: 'Breakout sessions are smaller group meetings held during conferences, workshops, or other large events. They divide attendees into groups that meet separately to discuss specific topics, practice skills, or work on projects. Breakout sessions offer several advantages: they allow deeper exploration of niche topics, encourage participation from attendees who may be reluctant to speak in large groups, and let participants customize their event experience by choosing sessions aligned with their interests. Effective breakout sessions have clear objectives, skilled facilitators, appropriate room assignments, and enough time for meaningful engagement. Organizers should consider factors such as room capacity, audiovisual needs, session duration, and how to communicate session options and locations to attendees.', category: 'events', relatedTerms: ['keynote', 'workshop', 'run-of-show', 'event-registration'], faqQuestions: [{ question: 'How long should a breakout session be?', answer: 'Most breakout sessions run 45-90 minutes, depending on the topic complexity and format. Allow 10-15 minutes between sessions for transitions.' }], keywords: ['breakout session', 'conference breakout', 'breakout session ideas', 'event breakout groups'] },
  { slug: 'capacity-planning', term: 'Capacity Planning', definition: 'The process of determining the maximum number of attendees an event can accommodate based on venue size, safety regulations, and resource availability.', extendedDefinition: 'Capacity planning ensures that events can safely and comfortably accommodate all attendees while meeting fire codes, accessibility requirements, and venue policies. Factors to consider include room layout and seating arrangements, fire marshal occupancy limits, accessibility requirements under the ADA, restroom availability, parking capacity, food and beverage service capacity, and emergency exit accessibility. Effective capacity planning also accounts for staff-to-attendee ratios, registration check-in flow, and session room sizes for breakout sessions. Organizations should establish maximum capacity numbers early in the planning process and implement registration limits, waitlists, or ticketing systems to manage attendance. For outdoor events, weather contingency plans should include indoor alternatives with appropriate capacity.', category: 'events', relatedTerms: ['event-registration', 'waitlist', 'venue-selection', 'run-of-show'], faqQuestions: [{ question: 'How do you determine event capacity?', answer: 'Start with the venue\'s official fire marshal capacity, then adjust based on your event layout, ADA requirements, and the type of event. A seated dinner needs more space per person than a standing reception.' }], keywords: ['event capacity planning', 'venue capacity', 'event capacity management', 'maximum event attendance'] },
  { slug: 'early-bird-registration', term: 'Early Bird Registration', definition: 'A discounted registration rate offered for a limited time before an event to incentivize early sign-ups. Early bird pricing helps organizers gauge attendance and improve cash flow.', extendedDefinition: 'Early bird registration offers attendees a reduced price for registering before a specified deadline. This pricing strategy benefits both organizers and attendees: organizers gain early revenue, can better predict attendance, and have more time to plan logistics, while attendees save money. Typical early bird discounts range from 10-25% off the regular price. Best practices include setting a clear deadline that is prominently displayed, limiting the number of early bird slots to create urgency, sending reminder emails as the deadline approaches, and offering multiple pricing tiers (super early bird, early bird, regular, late registration). The early bird period typically ends 4-8 weeks before the event, giving organizers time to finalize arrangements based on registrations received.', category: 'events', relatedTerms: ['event-registration', 'event-ticketing', 'waitlist', 'capacity-planning'], faqQuestions: [{ question: 'What is a typical early bird discount?', answer: 'Most events offer 10-25% off the regular price for early bird registration. Some organizations offer a steeper discount for a "super early bird" period and a smaller discount for the standard early bird window.' }], keywords: ['early bird registration', 'early bird pricing', 'event early bird discount', 'early bird ticket'] },
  { slug: 'event-check-in', term: 'Event Check-In', definition: 'The process of confirming attendee arrival and providing them with necessary materials like name badges, programs, and access credentials. Modern check-in often uses QR codes or mobile apps.', extendedDefinition: 'Event check-in is the first impression attendees have of an event and sets the tone for the entire experience. An efficient check-in process minimizes wait times, accurately tracks attendance, and provides attendees with everything they need. Traditional methods include printed registration lists and manual name badge distribution, while modern approaches use QR code scanning, self-service kiosks, mobile app check-in, and RFID wristbands. Key considerations include staffing the check-in area adequately for peak arrival times, organizing materials alphabetically or by registration type, having a process for handling walk-in registrations, and capturing attendance data for post-event analysis. GatherGrove supports QR code check-in that allows organizers to scan attendee tickets and instantly verify registration status, update attendance records, and track arrival patterns.', category: 'events', relatedTerms: ['event-registration', 'qr-code', 'rsvp', 'no-show-rate'], faqQuestions: [{ question: 'What is the fastest way to check in event attendees?', answer: 'QR code scanning is the fastest method. Each attendee receives a unique QR code that can be scanned with a smartphone or tablet, instantly confirming their registration and marking them as checked in.' }], keywords: ['event check-in', 'event check in process', 'QR code event check-in', 'event attendance tracking'] },
  { slug: 'event-feedback', term: 'Event Feedback', definition: 'Structured input collected from attendees after an event to evaluate satisfaction, identify improvements, and measure the event\'s success against its objectives.', extendedDefinition: 'Event feedback is essential for continuous improvement of an organization\'s events. Collection methods include post-event surveys (the most common), live polling during sessions, comment cards, social media monitoring, and one-on-one interviews with key stakeholders. Effective feedback surveys are concise (5-10 questions), sent within 24-48 hours of the event, and include a mix of quantitative ratings and open-ended questions. Key metrics to measure include overall satisfaction, likelihood to attend again (Net Promoter Score), session quality ratings, venue and logistics satisfaction, and suggestions for improvement. Organizations should analyze feedback trends over time, share results with the planning team and stakeholders, and visibly act on feedback in future events. Closing the feedback loop by telling attendees how their input influenced changes builds trust and encourages future participation.', category: 'events', relatedTerms: ['post-event-survey', 'event-registration', 'no-show-rate', 'event-sponsorship'], faqQuestions: [{ question: 'When should you send a post-event survey?', answer: 'Send the survey within 24-48 hours of the event while the experience is fresh. Keep it short (5-10 minutes to complete) and consider offering an incentive for completion to improve response rates.' }], keywords: ['event feedback', 'post-event feedback', 'event survey', 'event evaluation'] },
  { slug: 'event-registration', term: 'Event Registration', definition: 'The process by which attendees sign up for an event, providing their information and often paying a fee. Registration systems collect data, manage capacity, and facilitate communication.', extendedDefinition: 'Event registration is the gateway to event attendance and a critical touchpoint for data collection and attendee management. A registration system should capture essential attendee information (name, email, dietary restrictions, accessibility needs), process payments securely, send confirmation emails and reminders, manage waitlists when events reach capacity, and provide organizers with real-time registration data. Modern registration platforms offer features like customizable forms, multiple ticket types, group registration, discount codes, and integration with payment processors. The registration experience significantly impacts an attendee\'s perception of the event and the organization. Best practices include keeping forms short, offering multiple payment options, sending immediate confirmation, providing clear event details and logistics, and making cancellation or transfer policies transparent.', category: 'events', relatedTerms: ['rsvp', 'event-ticketing', 'waitlist', 'early-bird-registration', 'event-check-in'], faqQuestions: [{ question: 'What information should an event registration form collect?', answer: 'At minimum: name, email, and payment (if applicable). Additional useful fields include phone number, dietary restrictions, accessibility needs, how they heard about the event, and any session or track preferences.' }], keywords: ['event registration', 'event sign up', 'online event registration', 'event registration form'] },
  { slug: 'event-sponsorship', term: 'Event Sponsorship', definition: 'A financial or in-kind contribution from a business or individual in exchange for brand visibility, access to attendees, or other promotional benefits at an event.', extendedDefinition: 'Event sponsorship is a mutually beneficial arrangement where sponsors provide funding or resources in exchange for exposure to the event\'s audience. Sponsorship packages typically include tiered levels (platinum, gold, silver, bronze) with corresponding benefits such as logo placement on event materials, booth or exhibit space, speaking opportunities, attendee list access, social media mentions, and branded materials in attendee bags. Effective sponsorship programs offer clear value propositions, measurable ROI metrics, and customization options. Organizations should develop sponsorship prospectuses that outline audience demographics, past event attendance, marketing reach, and specific benefits at each level. Post-event, sponsors should receive fulfillment reports documenting how their benefits were delivered, including attendance numbers, social media impressions, and photos of their branding.', category: 'events', relatedTerms: ['event-registration', 'in-kind-donation', 'fundraising', 'capacity-planning'], faqQuestions: [{ question: 'How do you price event sponsorship levels?', answer: 'Base pricing on the value of benefits provided, comparable events in your market, your audience size and demographics, and the total event budget. Typical sponsorship revenue targets are 20-40% of total event costs.' }], keywords: ['event sponsorship', 'sponsorship packages', 'event sponsor benefits', 'sponsorship levels'] },
  { slug: 'event-ticketing', term: 'Event Ticketing', definition: 'The system for selling, distributing, and validating admission tickets for events. Ticketing platforms handle pricing tiers, payment processing, and access control.', extendedDefinition: 'Event ticketing encompasses the entire process of selling admission to events, from creating ticket types and pricing to distributing tickets and validating them at the door. Modern ticketing platforms offer digital tickets with QR codes, multiple ticket types (general admission, VIP, early bird, group), payment processing with various methods, automated confirmation and reminder emails, transfer and refund capabilities, and real-time sales dashboards. When choosing a ticketing solution, organizations should consider platform fees and payment processing costs, ease of use for both administrators and attendees, integration with other tools like email marketing and CRM systems, reporting and analytics capabilities, and customer support availability. The ticketing process also provides valuable data about your audience that can be used for marketing future events and building member relationships.', category: 'events', relatedTerms: ['event-registration', 'early-bird-registration', 'event-check-in', 'qr-code'], faqQuestions: [{ question: 'What fees should you expect from event ticketing platforms?', answer: 'Most platforms charge per-ticket fees (typically $0.50-$2.00 plus 2-5% of the ticket price). Some platforms offer flat monthly subscriptions instead. Consider whether to absorb fees or pass them on to attendees.' }], keywords: ['event ticketing', 'online ticketing', 'event ticket sales', 'ticketing platform'] },
  { slug: 'hybrid-event', term: 'Hybrid Event', definition: 'An event that combines in-person and virtual attendance options, allowing participants to join either physically at the venue or remotely via live stream or video conferencing.', extendedDefinition: 'Hybrid events provide the best of both worlds by offering a physical venue experience alongside virtual participation options. This format became widespread during the COVID-19 pandemic and has remained popular because it expands reach, increases accessibility, and provides flexibility for attendees. Successfully executing a hybrid event requires investment in technology (cameras, microphones, streaming platform), thoughtful content design that engages both audiences, dedicated moderators for virtual attendees, and a production plan that integrates both experiences. Challenges include maintaining engagement for virtual attendees who may feel disconnected, managing technology issues, and pricing tickets appropriately for the different experience levels. Best practices include assigning a dedicated team to manage the virtual experience, incorporating interactive elements like polls and Q&A for both audiences, and recording sessions for on-demand viewing afterward.', category: 'events', relatedTerms: ['keynote', 'breakout-session', 'event-registration', 'event-feedback'], faqQuestions: [{ question: 'How do you keep virtual attendees engaged at a hybrid event?', answer: 'Assign a dedicated virtual moderator, include interactive elements (polls, Q&A, chat), provide virtual networking opportunities, and ensure high-quality audio and video. Consider virtual-only breakout rooms for remote attendees to connect.' }], keywords: ['hybrid event', 'hybrid meeting', 'hybrid event best practices', 'in-person and virtual event'] },
  { slug: 'keynote', term: 'Keynote', definition: 'The main featured presentation at an event, typically delivered by a prominent speaker who sets the tone and theme for the gathering. Keynotes are usually held in the largest venue to accommodate all attendees.', extendedDefinition: 'A keynote presentation is the centerpiece of a conference, summit, or major event. It is designed to be the highlight that draws attendance, establishes the event\'s theme, and creates a shared experience for all participants. Keynote speakers are usually chosen for their expertise, reputation, speaking ability, and relevance to the audience. They may be industry leaders, authors, subject matter experts, or motivational speakers. Event organizers typically allocate the largest budget to keynote speakers, with fees ranging from no charge (for members or volunteers) to thousands of dollars for professional speakers. Effective keynotes are 30-60 minutes long, tell a compelling story, provide actionable insights, and leave the audience inspired. Organizers should work closely with keynote speakers beforehand to ensure content alignment with the event\'s theme and audience expectations.', category: 'events', relatedTerms: ['breakout-session', 'workshop', 'run-of-show', 'event-sponsorship'], faqQuestions: [{ question: 'How long should a keynote speech be?', answer: 'Most keynotes are 30-60 minutes, including any Q&A. The ideal length depends on the event format and audience, but 45 minutes of speaking plus 15 minutes of Q&A is a common and effective format.' }], keywords: ['keynote speaker', 'keynote presentation', 'event keynote', 'conference keynote'] },
  { slug: 'no-show-rate', term: 'No-Show Rate', definition: 'The percentage of registered attendees who do not attend an event without canceling. Tracking no-show rates helps organizations plan more accurately for future events.', extendedDefinition: "The no-show rate is calculated by dividing the number of registered attendees who did not show up by the total number of registrations. For free events, no-show rates can be as high as 30-50%, while paid events typically see 5-15% no-shows. The rate also varies significantly by club event type: casual social mixers tend to have higher no-show rates than structured skill workshops or ticketed dinners, because the perceived cost of skipping is lower. High no-show rates lead to wasted resources - over-catered food, unnecessarily large venue bookings, and the deflated atmosphere of a half-empty room. Strategies to reduce no-shows for club events include charging even a modest registration fee (which significantly increases commitment), sending a reminder sequence (one week out, one day out, and morning-of for day events), requiring RSVP confirmation with a clear cancellation link so spots can be released to others, and communicating who else is attending to build anticipation. Waitlists are a particularly effective tool: when registered members know others are waiting for their spot, they are more likely to cancel in time rather than simply not showing up. For recurring events, tracking your club's no-show rate over time helps set realistic headcounts for catering, materials, and room bookings. Some clubs apply a no-show policy - such as priority registration for consistently attending members - to reward reliability without penalizing first-timers.", category: 'events', relatedTerms: ['rsvp', 'event-registration', 'waitlist', 'event-check-in'], faqQuestions: [{ question: 'What is a normal no-show rate for events?', answer: "Free events typically see 30-50% no-shows, while paid events see 5-15%. The rate varies by event type, audience, weather, and time of year. Tracking your organization's specific rates over time provides the most useful planning data." }, { question: 'How does a waitlist help reduce no-show impact?', answer: 'A waitlist reduces the impact of no-shows in two ways: it fills vacated spots automatically when registrants cancel, and it creates social accountability - members who know others are waiting for their seat are more motivated to cancel properly rather than simply not attending. Enable waitlists for any event with limited capacity.' }, { question: 'Should I charge a cancellation fee for no-shows at club events?', answer: "Charging a flat cancellation fee (rather than withholding a refund) can be difficult to enforce and may create resentment. Most clubs find better results by making cancellation easy - a one-click cancel link in the confirmation email - and by setting a clear cancellation deadline so spots can be offered to waitlisted members. Reserve penalty policies for repeat offenders or high-cost events like banquets." }], keywords: ['event no-show rate', 'no-show rate', 'reduce event no-shows', 'event attendance rate', 'club event attendance', 'event registration no-show policy'] },
  { slug: 'post-event-survey', term: 'Post-Event Survey', definition: 'A questionnaire sent to attendees after an event to collect feedback on their experience, measure satisfaction, and gather suggestions for improvement.', extendedDefinition: 'Post-event surveys are a critical tool for evaluating event success and planning future improvements. Effective surveys balance quantitative metrics (rating scales) with qualitative feedback (open-ended questions). Key areas to evaluate include overall satisfaction, session and speaker quality, venue and logistics, registration and check-in experience, food and beverage, networking opportunities, and likelihood to attend future events. Best practices include keeping the survey to 5-10 questions, sending it within 24-48 hours of the event, using a mix of rating scales and open-ended questions, including a Net Promoter Score question, offering an incentive for completion, and making it mobile-friendly. Response rates for post-event surveys typically range from 15-30% for general events and can be higher for smaller, more engaged groups. Results should be compiled into an event report and shared with the planning team, board, and sponsors as appropriate.', category: 'events', relatedTerms: ['event-feedback', 'no-show-rate', 'event-registration', 'rsvp'], faqQuestions: [{ question: 'What questions should be on a post-event survey?', answer: 'Include overall satisfaction rating, specific session ratings, what they liked most and least, suggestions for improvement, likelihood to attend again (NPS), and demographic questions if needed for planning.' }], keywords: ['post-event survey', 'event survey questions', 'event feedback survey', 'post-event evaluation'] },
  { slug: 'qr-code', term: 'QR Code', definition: 'A two-dimensional barcode that can be scanned by smartphones to quickly access information, verify tickets, or check in attendees. QR codes streamline event operations and reduce paper waste.', extendedDefinition: 'QR (Quick Response) codes have become an essential tool in event management. They serve multiple purposes: attendee check-in (each registrant receives a unique QR code that can be scanned at the door for instant verification), digital tickets (replacing paper tickets with scannable codes on smartphones), information sharing (linking to event schedules, speaker bios, venue maps, or WiFi credentials), and networking (attendees can exchange contact information by scanning each other\'s QR codes). QR codes are cost-effective because they eliminate the need for printed materials and reduce check-in staff requirements. They also provide real-time data - organizers can track exactly when each attendee arrived, which sessions they attended, and how they moved through the event. When implementing QR codes, ensure reliable internet connectivity at scanning stations, have a backup plan for attendees who cannot display their code, and test the scanning system thoroughly before the event.', category: 'events', relatedTerms: ['event-check-in', 'event-ticketing', 'event-registration', 'hybrid-event'], faqQuestions: [{ question: 'How do QR codes work for event check-in?', answer: 'Each registered attendee receives a unique QR code via email. At the event, staff scan the code using a smartphone or tablet app. The system instantly verifies registration, marks the attendee as checked in, and updates attendance records in real time.' }], keywords: ['QR code events', 'QR code check-in', 'event QR code', 'QR code scanner events'] },
  { slug: 'rsvp', term: 'RSVP', definition: 'A response to an invitation indicating whether the invitee plans to attend. RSVP comes from the French phrase "répondez s\'il vous plaît" (please respond) and helps organizers plan for accurate headcounts.', extendedDefinition: 'RSVP is a request for attendees to confirm or decline attendance at an event. Accurate RSVPs are essential for event planning because they determine catering orders, seating arrangements, material quantities, room setup, and staffing needs. Modern RSVP systems go beyond simple yes/no responses to include meal preferences, accessibility needs, plus-one information, and session selections. Digital RSVP tools have largely replaced paper response cards, offering real-time tracking, automated reminders, easy updates, and integration with event management platforms. Best practices for maximizing RSVP response rates include setting a clear deadline, making it easy to respond (one-click RSVP links), sending reminders to non-respondents, and following up personally for important events. Organizations should also plan for a gap between RSVPs and actual attendance, using historical data to estimate the likely no-show rate.', category: 'events', relatedTerms: ['event-registration', 'no-show-rate', 'waitlist', 'event-check-in'], faqQuestions: [{ question: 'What does RSVP stand for?', answer: 'RSVP stands for "répondez s\'il vous plaît," a French phrase meaning "please respond." It is a request for the invitee to indicate whether they plan to attend the event.' }], keywords: ['RSVP meaning', 'RSVP', 'event RSVP', 'RSVP tracking', 'répondez s\'il vous plaît'] },
  { slug: 'run-of-show', term: 'Run of Show', definition: 'A detailed, minute-by-minute timeline of an event that specifies what happens when, who is responsible, and what technical requirements are needed at each point.', extendedDefinition: 'A run of show (ROS) document is the master operational timeline for an event, providing a detailed sequence of every activity from setup through teardown. It includes exact start and end times for each segment, descriptions of what happens during each segment, the person or team responsible for each item, technical requirements (microphones, projectors, lighting changes, music cues), and stage directions and transitions. The run of show serves as the single source of truth that coordinates all event stakeholders - speakers, AV technicians, catering, volunteers, and venue staff. A well-crafted ROS includes buffer time between segments, identifies potential bottleneck points, and has contingency plans for common issues like sessions running long or technical difficulties. The document should be created collaboratively, reviewed by all key stakeholders, and distributed well in advance of the event with final updates provided the day before.', category: 'events', relatedTerms: ['keynote', 'breakout-session', 'event-check-in', 'capacity-planning'], faqQuestions: [{ question: 'What should be included in a run of show?', answer: 'Include time stamps, activity descriptions, responsible persons, technical requirements (AV, lighting, music), speaker names, room assignments, and transition notes. Also include setup and teardown schedules and contact information for all key personnel.' }], keywords: ['run of show', 'event timeline', 'run of show template', 'event schedule template'] },
  { slug: 'venue-selection', term: 'Venue Selection', definition: 'The process of evaluating and choosing a location for an event based on capacity, cost, accessibility, amenities, and alignment with the event\'s purpose and audience.', extendedDefinition: 'Venue selection is one of the most impactful decisions in event planning, affecting everything from attendance to atmosphere to budget. Key factors to consider include capacity and layout flexibility, location and accessibility (public transit, parking, ADA compliance), cost and what is included in the rental fee, available technology and AV equipment, catering options and restrictions, insurance requirements, cancellation policies, and the venue\'s overall aesthetic and alignment with your event brand. Organizations should visit potential venues in person, ask for references from previous clients, and carefully review contracts for hidden fees or restrictive policies. Common venue types include hotels, conference centers, community centers, restaurants, parks, museums, and co-working spaces. For recurring events, negotiating a multi-event contract with a preferred venue can reduce costs and simplify logistics.', category: 'events', relatedTerms: ['capacity-planning', 'event-registration', 'run-of-show', 'event-sponsorship'], faqQuestions: [{ question: 'What are the most important factors in choosing an event venue?', answer: 'The top factors are capacity (fits your expected attendance), location (accessible to your audience), cost (within budget), and amenities (AV, catering, parking). Also consider accessibility, ambiance, and the venue\'s flexibility for your specific needs.' }], keywords: ['venue selection', 'event venue', 'choosing event venue', 'venue selection criteria'] },
  { slug: 'waitlist', term: 'Waitlist', definition: 'An ordered list of people who want to attend a sold-out or full-capacity event. When spots open up through cancellations, waitlisted individuals are offered the opportunity to register in order.', extendedDefinition: 'A waitlist is a queue management system that allows organizations to capture demand beyond an event\'s capacity and fill spots that open up due to cancellations or transfers. When an event reaches its maximum capacity, additional interested attendees are added to the waitlist in order of their request. When a spot becomes available, the first person on the waitlist is notified and given a limited time to confirm their registration before the spot is offered to the next person. Effective waitlist management includes automated notifications when spots open, clear deadlines for accepting offered spots, the ability for waitlisted individuals to check their position, and communication about the likelihood of getting in. Waitlists also provide valuable data - a consistently long waitlist signals that the organization should consider larger venues, additional event dates, or virtual attendance options for future events.', category: 'events', relatedTerms: ['event-registration', 'capacity-planning', 'no-show-rate', 'rsvp'], faqQuestions: [{ question: 'How should you manage an event waitlist?', answer: 'Use automated notifications to alert waitlisted people when spots open, give a clear deadline (24-48 hours) to accept, and automatically move to the next person if declined. Track waitlist size to inform future event planning.' }], keywords: ['event waitlist', 'waitlist management', 'event waitlist system', 'managing event capacity'] },
  { slug: 'workshop', term: 'Workshop', definition: 'An interactive, hands-on learning session where participants actively engage with material through exercises, discussions, or projects rather than passively listening to a presentation.', extendedDefinition: 'Workshops are participatory educational sessions designed for active learning and skill development. Unlike lectures or presentations where information flows one way, workshops involve attendees in the learning process through activities, group discussions, case studies, role-playing, demonstrations, and practice exercises. Effective workshops have clear learning objectives, a skilled facilitator who can manage group dynamics, appropriate materials and supplies, and enough time for both instruction and practice. Workshop sizes are typically smaller than general sessions - usually 15-30 participants - to allow for meaningful interaction and individual attention. When planning workshops, consider the skill level of participants, whether pre-work is required, what materials participants need to bring, and how outcomes will be assessed. Post-workshop follow-up, such as resource packets or online communities, can help participants continue their learning after the event.', category: 'events', relatedTerms: ['breakout-session', 'keynote', 'event-registration', 'event-feedback'], faqQuestions: [{ question: 'What is the ideal size for a workshop?', answer: 'Most workshops work best with 15-30 participants. This size allows for meaningful group activities and individual attention while still creating diverse perspectives. For hands-on skills training, even smaller groups of 8-12 may be more effective.' }], keywords: ['workshop', 'interactive workshop', 'workshop planning', 'workshop vs presentation'] },
  { slug: 'event-agenda', term: 'Event Agenda', definition: 'A structured outline of an event\'s schedule, including session times, topics, speakers, locations, and breaks. The agenda guides attendees through the event and helps organizers manage time.', extendedDefinition: "An event agenda provides a clear overview of what attendees can expect and when. For club meetings following Robert's Rules of Order, the standard agenda format is: (1) Call to order, (2) Roll call or attendance, (3) Approval of the previous meeting's minutes, (4) Officer reports (president, treasurer, committee chairs), (5) Old business (items carried over from previous meetings), (6) New business (new items introduced at this meeting), (7) Announcements, (8) Adjournment. Distributing this agenda to members at least 48 hours before the meeting - by email or through a member portal - allows them to prepare motions, gather information, and budget their time. For larger events like annual galas, training days, or multi-session workshops, the agenda expands to include session descriptions, speaker bios, room assignments, catering breaks, and networking windows. A well-designed agenda for these events balances content density with recovery time, typically scheduling demanding sessions in the morning when energy is highest and lighter networking or Q&A in the afternoon. Digital agendas distributed through event apps or club management software allow real-time updates if speakers change or sessions run long. Organizations should always share a final agenda at least 1-2 weeks before the event and make printed copies available at the door. After the event, the agenda becomes part of the historical record alongside meeting minutes, helping future organizers understand what worked and how long activities actually took.", category: 'events', relatedTerms: ['run-of-show', 'keynote', 'breakout-session', 'workshop'], faqQuestions: [{ question: 'How far in advance should an event agenda be published?', answer: 'Share a preliminary agenda 4-6 weeks before the event to help attendees plan, with a final version 1-2 weeks before. Allow for minor adjustments but avoid major changes close to the event date.' }, { question: "What is the standard format for a club meeting agenda?", answer: "A standard Robert's Rules club meeting agenda follows this order: call to order, roll call (if required), approval of previous minutes, officer reports, committee reports, old business, new business, announcements, adjournment. Many clubs add a brief social period before or after the formal agenda to encourage member connection." }, { question: 'How should I handle agenda items that run over time?', answer: "Set a time limit for each agenda item when you distribute the agenda, and appoint someone to track time. When an item runs over, the chair can ask for a motion to extend time (in Robert's Rules) or simply table the item to the next meeting. Keeping meetings to their scheduled end time builds trust and improves attendance over time." }], keywords: ['event agenda', 'meeting agenda', 'event schedule', 'conference agenda template', 'club meeting agenda template', 'meeting agenda format', 'how to create a meeting agenda'] },
  { slug: 'event-budget', term: 'Event Budget', definition: 'A detailed financial plan that estimates all income and expenses associated with producing an event. The budget guides spending decisions and tracks actual costs against projections.', extendedDefinition: 'An event budget is a comprehensive financial document that outlines all anticipated revenue sources and expenses for an event. Revenue typically includes registration fees, sponsorships, ticket sales, merchandise, and donations. Expenses include venue rental, catering, speakers, AV and technology, marketing and promotion, printing, staffing, insurance, decorations, and contingency reserves. Best practices for event budgeting include building in a 10-15% contingency fund for unexpected costs, tracking actual expenses against the budget in real time, categorizing expenses to identify the biggest cost drivers, negotiating contracts and getting multiple bids for major expenses, and conducting a post-event financial review. Historical data from previous events is invaluable for creating accurate budgets. Organizations should establish approval thresholds for expenses and maintain clear documentation of all financial decisions.', category: 'events', relatedTerms: ['event-sponsorship', 'event-registration', 'event-ticketing', 'annual-budget'], faqQuestions: [{ question: 'How much contingency should be included in an event budget?', answer: 'Include a contingency fund of 10-15% of the total budget to cover unexpected costs. For first-time events, consider 15-20% since there is less historical data to base estimates on.' }], keywords: ['event budget', 'event budget template', 'event budgeting', 'event cost planning'] },
  { slug: 'event-marketing', term: 'Event Marketing', definition: 'The strategies and tactics used to promote an event and drive attendance, including email campaigns, social media, partnerships, and paid advertising.', extendedDefinition: 'Event marketing encompasses all promotional activities designed to generate awareness, interest, and registrations for an event. An effective event marketing plan uses multiple channels: email marketing (the most effective channel for driving registrations for most organizations), social media (organic posts, paid ads, event pages, influencer partnerships), website and landing pages (with compelling copy, clear calls to action, and easy registration), content marketing (blog posts, videos, speaker interviews), partnerships and cross-promotion (with sponsors, related organizations, and media partners), and word of mouth (member referrals, early bird incentives for sharing). The marketing timeline should begin 8-12 weeks before the event for large events and 4-6 weeks for smaller ones. Key metrics to track include website traffic, registration conversion rate, email open and click rates, social media engagement, and cost per registration.', category: 'events', relatedTerms: ['event-registration', 'event-sponsorship', 'early-bird-registration', 'email-automation'], faqQuestions: [{ question: 'How early should event marketing begin?', answer: 'For large events, begin marketing 8-12 weeks in advance. For smaller events, 4-6 weeks is typically sufficient. Send a save-the-date even earlier for annual or major events to get on people\'s calendars.' }], keywords: ['event marketing', 'promote event', 'event promotion', 'event marketing strategy'] },
]

// ── volunteer (25 entries, alphabetical) ──────────────────────────────────
const volunteer: GlossaryEntry[] = [
  { slug: 'background-check', term: 'Background Check', definition: 'A screening process that reviews an individual\'s criminal history, references, and qualifications before they are approved to volunteer, especially for positions involving children, vulnerable adults, or financial responsibilities.', extendedDefinition: 'Background checks are a critical risk management practice for organizations that use volunteers, particularly those working with minors, elderly, disabled individuals, or handling money. The screening process may include criminal history checks at local, state, and national levels, sex offender registry searches, reference checks, employment verification, and driving record reviews for positions requiring transportation. Organizations should establish clear policies about which volunteer roles require background checks, how the results are evaluated, and how records are maintained. Many organizations use third-party screening services that specialize in volunteer background checks. It is important to comply with the Fair Credit Reporting Act (FCRA) and state-specific regulations regarding consent, disclosure, and adverse action procedures. The cost of background checks is typically borne by the organization, not the volunteer.', category: 'volunteer', relatedTerms: ['volunteer-agreement', 'volunteer-coordinator', 'volunteer-onboarding', 'risk-management'], faqQuestions: [{ question: 'Should all volunteers undergo background checks?', answer: 'Not necessarily all, but organizations should conduct background checks for volunteers working with children or vulnerable adults, handling finances, having unsupervised access to facilities, or serving in positions of trust.' }], keywords: ['volunteer background check', 'background check for volunteers', 'volunteer screening', 'nonprofit background checks'] },
  { slug: 'community-service-hours', term: 'Community Service Hours', definition: 'Documented time spent by individuals performing volunteer work for community benefit. Many schools, courts, and professional organizations require or incentivize a specific number of community service hours.', extendedDefinition: 'Community service hours are the recorded time individuals spend volunteering for organizations that benefit the public. Tracking these hours is important for multiple stakeholders: students who need service hours for graduation requirements, court-ordered community service fulfillment, scholarship applicants who must demonstrate civic engagement, employees participating in corporate volunteer programs, and organizations that report volunteer contributions for grant applications and community impact measurement. Accurate tracking systems should record the volunteer\'s name, date, hours, and type of activity. Digital volunteer management platforms can automate this process with check-in and check-out features, hour verification by supervisors, and automatic report generation. Organizations should provide clear documentation that meets the requirements of the referring institution, whether that is a school, court, or employer.', category: 'volunteer', relatedTerms: ['service-learning', 'volunteer-hours-tracking', 'volunteer-recognition', 'volunteer-coordinator'], faqQuestions: [{ question: 'How should organizations verify community service hours?', answer: 'Use a supervisor sign-off system where the volunteer checks in and out, and a staff member or volunteer coordinator verifies the hours. Digital tracking systems can automate this with timestamps and supervisor approval workflows.' }], keywords: ['community service hours', 'volunteer hours', 'service hours tracking', 'community service requirements'] },
  { slug: 'corporate-volunteerism', term: 'Corporate Volunteerism', definition: 'Programs where companies encourage or organize employee volunteer activities, often providing paid time off for volunteering or matching employee volunteer hours with charitable donations.', extendedDefinition: 'Corporate volunteerism (also called corporate community engagement or employee volunteering) refers to company-sponsored programs that facilitate and encourage employees to volunteer their time and skills to nonprofit organizations and community causes. These programs take various forms: paid volunteer time off (VTO), where employees receive regular pay while volunteering; team volunteer projects, where groups of employees work together on a specific project; skills-based volunteering, where professionals provide pro bono services in their area of expertise; and dollars-for-doers programs, where the company makes a donation to the nonprofit for each hour an employee volunteers. For nonprofits, corporate volunteer partnerships can provide skilled labor, increase capacity, and lead to corporate sponsorships and donations. To attract corporate volunteers, organizations should offer well-organized, meaningful projects with clear start and end times that accommodate business schedules.', category: 'volunteer', relatedTerms: ['volunteer-recognition', 'in-kind-donation', 'volunteer-coordinator', 'volunteer-retention'], faqQuestions: [{ question: 'How can a nonprofit attract corporate volunteers?', answer: 'Develop well-organized, turnkey volunteer projects that fit into a business day. Reach out to local companies\' community engagement or HR departments. Offer team-building activities, impact measurement, and recognition that companies can share with stakeholders.' }], keywords: ['corporate volunteerism', 'employee volunteering', 'corporate volunteer programs', 'VTO volunteer time off'] },
  { slug: 'episodic-volunteer', term: 'Episodic Volunteer', definition: 'A person who volunteers on a short-term or one-time basis for specific events or projects rather than making an ongoing commitment. Episodic volunteering is the fastest-growing segment of the volunteer workforce.', extendedDefinition: 'Episodic volunteers participate in volunteer activities that have a defined beginning and end, typically a single event or short-term project. This contrasts with traditional or ongoing volunteers who commit to regular, long-term service. Episodic volunteering has grown significantly as people\'s schedules have become more complex and the desire for flexibility has increased. Examples include volunteering at a charity run, helping with a food drive, participating in a park cleanup day, or staffing a one-time fundraising event. Organizations should adapt their volunteer management practices to accommodate episodic volunteers by providing clear role descriptions that can be learned quickly, minimizing training requirements, creating self-contained tasks that can be completed in one session, offering a range of commitment levels, and making the sign-up process easy and flexible. Episodic volunteers can become ongoing volunteers over time if their experience is positive.', category: 'volunteer', relatedTerms: ['volunteer-retention', 'volunteer-onboarding', 'volunteer-coordinator', 'volunteer-recognition'], faqQuestions: [{ question: 'How do you convert episodic volunteers into regular volunteers?', answer: 'Provide an excellent first experience, express genuine appreciation, follow up within a week with a thank-you and information about ongoing opportunities, make it easy to sign up again, and gradually increase their involvement if they show interest.' }], keywords: ['episodic volunteer', 'one-time volunteer', 'short-term volunteering', 'volunteer flexibility'] },
  { slug: 'in-kind-volunteer', term: 'In-Kind Volunteer', definition: 'A volunteer who contributes specific professional skills or services rather than general labor. Also called a skills-based volunteer, they provide expertise in areas like accounting, legal, marketing, or technology.', extendedDefinition: 'In-kind or skills-based volunteers provide their professional expertise pro bono to organizations that may not be able to afford these services. Common examples include accountants preparing financial statements, lawyers reviewing contracts, web developers building websites, graphic designers creating marketing materials, and IT professionals setting up technology systems. Skills-based volunteering delivers significantly more value per hour than general volunteering - some studies estimate that a skilled volunteer\'s contribution is worth 2-3 times the value of general volunteer work. Organizations can attract skills-based volunteers by posting specific project descriptions that clearly define the skills needed, expected time commitment, and outcomes. Platforms like Catchafire, Taproot Foundation, and local volunteer centers specialize in matching skilled professionals with nonprofits. Organizations should treat skills-based volunteers professionally, providing clear project briefs, deadlines, and feedback.', category: 'volunteer', relatedTerms: ['corporate-volunteerism', 'volunteer-recognition', 'in-kind-donation', 'volunteer-coordinator'], faqQuestions: [{ question: 'How can an organization attract skills-based volunteers?', answer: 'Post specific project descriptions on platforms like Catchafire or Taproot. Network with local professional associations, reach out to corporate volunteer programs, and create well-defined projects with clear deliverables and timelines.' }], keywords: ['skills-based volunteer', 'pro bono volunteer', 'professional volunteering', 'in-kind volunteer services'] },
  { slug: 'risk-management', term: 'Risk Management', definition: 'The process of identifying, assessing, and mitigating potential risks to an organization, its volunteers, and the communities it serves. Risk management includes insurance, waivers, safety protocols, and training.', extendedDefinition: 'Risk management in the volunteer context involves systematically identifying and addressing potential hazards and liabilities associated with volunteer activities. Key components include conducting risk assessments for all volunteer activities, obtaining appropriate insurance coverage (general liability, volunteer accident, directors and officers), requiring waivers and releases of liability from volunteers, implementing safety protocols and emergency procedures, providing adequate training for all volunteer roles, conducting background checks for sensitive positions, maintaining proper supervision ratios, documenting incidents and near-misses, and reviewing and updating risk management plans annually. Organizations should balance the need for safety with the practical reality that excessive rules and paperwork can discourage volunteer participation. The goal is to create a culture of safety awareness without creating unnecessary barriers to service.', category: 'volunteer', relatedTerms: ['background-check', 'volunteer-agreement', 'volunteer-onboarding', 'volunteer-coordinator'], faqQuestions: [{ question: 'What insurance do organizations need for volunteers?', answer: 'At minimum, general liability insurance. Consider adding volunteer accident/medical coverage, directors and officers (D&O) insurance, and workers\' compensation if required by your state for volunteers. Consult an insurance professional familiar with nonprofits.' }], keywords: ['volunteer risk management', 'nonprofit risk management', 'volunteer insurance', 'volunteer liability'] },
  { slug: 'service-learning', term: 'Service Learning', definition: 'An educational approach that combines classroom learning with meaningful community service. Students apply academic skills to real-world situations while addressing genuine community needs.', extendedDefinition: 'Service learning is a structured form of experiential education that integrates community service with academic instruction and reflection. Unlike general community service (which focuses primarily on the service), service learning has explicit learning objectives that connect the service experience to curriculum content. The key components are preparation (learning about the community need and relevant academic concepts), action (performing meaningful service), reflection (critically analyzing the experience and connecting it to learning goals), and demonstration (sharing what was learned). Service learning benefits both the students (developing academic skills, civic responsibility, and career readiness) and the community organizations (receiving valuable help while shaping the next generation of engaged citizens). Organizations that host service learning students should work closely with educators to align projects with learning objectives and provide structured reflection opportunities.', category: 'volunteer', relatedTerms: ['community-service-hours', 'volunteer-onboarding', 'episodic-volunteer', 'volunteer-coordinator'], faqQuestions: [{ question: 'What is the difference between community service and service learning?', answer: 'Community service focuses on providing help to the community. Service learning adds an intentional educational component - students reflect on the experience and connect it to academic learning objectives. Service learning requires preparation, action, reflection, and demonstration.' }], keywords: ['service learning', 'service-learning', 'experiential education', 'community service education'] },
  { slug: 'volunteer-agreement', term: 'Volunteer Agreement', definition: 'A written document that outlines the expectations, responsibilities, and terms of a volunteer\'s service with an organization. It protects both the volunteer and the organization by establishing clear guidelines.', extendedDefinition: 'A volunteer agreement (sometimes called a volunteer commitment form or memorandum of understanding) is a document that formalizes the relationship between a volunteer and the organization. While it is typically not a legally binding employment contract, it serves important purposes: establishing mutual expectations, documenting the volunteer\'s role and responsibilities, outlining the organization\'s commitments (training, supervision, reimbursement policies), addressing confidentiality and data protection, setting behavior standards and codes of conduct, and providing the basis for addressing issues if expectations are not met. The agreement may also include liability waivers, photo release permissions, and emergency contact information. Best practices include having volunteers review and sign the agreement during the onboarding process, keeping signed copies on file, and reviewing agreements annually to ensure they remain current and relevant.', category: 'volunteer', relatedTerms: ['volunteer-onboarding', 'background-check', 'volunteer-coordinator', 'risk-management'], faqQuestions: [{ question: 'Is a volunteer agreement legally binding?', answer: 'A volunteer agreement is generally not a legally binding employment contract. However, specific provisions like confidentiality clauses, liability waivers, and media releases may be enforceable depending on jurisdiction. Consult a lawyer for your specific situation.' }], keywords: ['volunteer agreement', 'volunteer contract', 'volunteer commitment form', 'volunteer MOU'] },
  { slug: 'volunteer-burnout', term: 'Volunteer Burnout', definition: 'A state of physical, emotional, and mental exhaustion experienced by volunteers who feel overwhelmed by demands on their time and energy. Burnout leads to disengagement and volunteer attrition.', extendedDefinition: 'Volunteer burnout occurs when volunteers are overworked, underappreciated, or feel their contributions are not making a meaningful difference. Signs of burnout include increased absences, declining quality of work, loss of enthusiasm, irritability, and eventually resignation. Common causes include asking too much of too few volunteers, lack of recognition and appreciation, unclear expectations or role ambiguity, organizational dysfunction or poor communication, feeling that their work does not matter, and being assigned tasks they find unfulfilling. Prevention strategies include distributing workload fairly across the volunteer team, setting clear boundaries and realistic expectations, regularly expressing genuine appreciation, providing variety in tasks and opportunities for growth, checking in regularly about satisfaction and workload, and making it easy for volunteers to take breaks without guilt. Organizations should monitor for signs of burnout and proactively address issues before losing valuable volunteers.', category: 'volunteer', relatedTerms: ['volunteer-retention', 'volunteer-recognition', 'volunteer-coordinator', 'volunteer-engagement'], faqQuestions: [{ question: 'How can organizations prevent volunteer burnout?', answer: 'Distribute workload fairly, set clear boundaries, express regular appreciation, provide variety in tasks, check in about satisfaction, ensure meaningful work, and make it acceptable to take breaks or say no to additional responsibilities.' }], keywords: ['volunteer burnout', 'volunteer exhaustion', 'prevent volunteer burnout', 'volunteer fatigue'] },
  { slug: 'volunteer-coordinator', term: 'Volunteer Coordinator', definition: 'The person responsible for recruiting, training, scheduling, supervising, and recognizing volunteers within an organization. This role may be a paid staff position or a volunteer leadership role.', extendedDefinition: 'A volunteer coordinator (also called volunteer manager or director of volunteers) is the central person responsible for all aspects of an organization\'s volunteer program. Their responsibilities typically include developing volunteer position descriptions, recruiting volunteers through various channels, screening and selecting volunteers (including background checks when needed), orienting and training new volunteers, creating and managing volunteer schedules, supervising and supporting volunteers during their service, tracking volunteer hours and contributions, planning recognition events and expressing appreciation, evaluating volunteer satisfaction and program effectiveness, and developing policies and procedures for the volunteer program. The effectiveness of a volunteer coordinator directly impacts volunteer retention, satisfaction, and the overall quality of the organization\'s volunteer program. Whether the role is paid or volunteer, the coordinator should have strong interpersonal skills, organizational abilities, and a genuine appreciation for the contributions of volunteers.', category: 'volunteer', relatedTerms: ['volunteer-onboarding', 'volunteer-retention', 'volunteer-recognition', 'volunteer-agreement'], faqQuestions: [{ question: 'What skills does a volunteer coordinator need?', answer: 'Key skills include strong communication and interpersonal abilities, organizational and time management skills, recruiting and marketing ability, conflict resolution, empathy and patience, and the ability to motivate and inspire others.' }], keywords: ['volunteer coordinator', 'volunteer manager', 'director of volunteers', 'volunteer coordinator duties'] },
  { slug: 'volunteer-engagement', term: 'Volunteer Engagement', definition: 'The degree to which volunteers are actively involved, emotionally connected, and committed to an organization\'s mission. Engaged volunteers contribute more time, perform better, and stay longer.', extendedDefinition: 'Volunteer engagement goes beyond simply having volunteers show up - it measures how connected and invested they feel in the organization\'s work. Engaged volunteers are enthusiastic about their roles, take initiative, advocate for the organization, and are more likely to increase their involvement over time. Key drivers of engagement include meaningful work that clearly connects to the mission, autonomy and trust in how they perform their tasks, opportunities for learning and personal growth, social connections with other volunteers and staff, regular feedback on their impact, involvement in decision-making, and alignment between their values and the organization\'s mission. Organizations can measure engagement through surveys, retention rates, average hours contributed, willingness to take on additional responsibilities, and recruitment of new volunteers through personal referrals.', category: 'volunteer', relatedTerms: ['volunteer-retention', 'volunteer-burnout', 'volunteer-recognition', 'volunteer-coordinator'], faqQuestions: [{ question: 'How do you measure volunteer engagement?', answer: 'Track metrics like retention rate, average hours per volunteer, willingness to take on new responsibilities, referral of new volunteers, survey satisfaction scores, and attendance at optional events. Qualitative conversations also reveal engagement levels.' }], keywords: ['volunteer engagement', 'engage volunteers', 'volunteer motivation', 'volunteer commitment'] },
  { slug: 'volunteer-hours-tracking', term: 'Volunteer Hours Tracking', definition: 'The systematic recording of time spent by volunteers performing service activities. Accurate tracking is essential for reporting, recognition, grant applications, and measuring organizational capacity.', extendedDefinition: 'Tracking volunteer hours provides valuable data for multiple purposes: demonstrating organizational impact to funders and stakeholders, calculating the economic value of volunteer contributions (using Independent Sector\'s annual value-per-hour estimate), verifying community service hours for students or court-ordered service, recognizing volunteers who reach hour milestones, planning staffing and scheduling, and reporting to grantmakers who require volunteer hour data. Tracking methods range from simple paper sign-in sheets to sophisticated digital platforms with GPS check-in, mobile apps, and automated reporting. When choosing a tracking system, consider ease of use for volunteers and administrators, ability to categorize hours by project or activity, reporting capabilities, integration with other management tools, and accuracy and verification methods. The system should be as frictionless as possible - complex or time-consuming tracking processes discourage accurate reporting.', category: 'volunteer', relatedTerms: ['community-service-hours', 'volunteer-coordinator', 'volunteer-recognition', 'volunteer-engagement'], faqQuestions: [{ question: 'What is the monetary value of a volunteer hour?', answer: 'Independent Sector publishes an annual estimate of the value of volunteer time. The national average is updated yearly and is commonly used in grant applications and impact reports to quantify volunteer contributions.' }], keywords: ['volunteer hours tracking', 'track volunteer hours', 'volunteer time tracking', 'volunteer hour log'] },
  { slug: 'volunteer-onboarding', term: 'Volunteer Onboarding', definition: 'The process of orienting, training, and integrating new volunteers into an organization. Effective onboarding sets expectations, builds confidence, and increases the likelihood of long-term volunteer retention.', extendedDefinition: 'Volunteer onboarding is the structured process of welcoming new volunteers and preparing them for success in their roles. A comprehensive onboarding process includes an orientation to the organization\'s mission, history, and culture; introduction to staff, other volunteers, and key contacts; role-specific training covering tasks, procedures, and expectations; a tour of facilities and relevant locations; distribution of necessary materials, credentials, or uniforms; review and signing of the volunteer agreement and policies; mentoring or buddy system pairing with experienced volunteers; and a clear point of contact for questions and support. Research shows that organizations with formal onboarding processes have significantly higher volunteer retention rates. The onboarding experience should make volunteers feel welcomed, valued, and confident in their ability to contribute. Follow up within the first week to check in on their experience and address any questions or concerns.', category: 'volunteer', relatedTerms: ['volunteer-coordinator', 'volunteer-agreement', 'volunteer-retention', 'background-check'], faqQuestions: [{ question: 'How long should volunteer onboarding take?', answer: 'The length varies by role complexity. Simple roles may require a 1-2 hour orientation, while complex positions might need several training sessions over 1-2 weeks. Include ongoing support and check-ins during the first month.' }], keywords: ['volunteer onboarding', 'new volunteer orientation', 'volunteer training', 'volunteer orientation process'] },
  { slug: 'volunteer-recognition', term: 'Volunteer Recognition', definition: 'The practices and programs used to acknowledge and appreciate the contributions of volunteers. Recognition increases volunteer satisfaction, motivation, and retention.', extendedDefinition: 'Volunteer recognition encompasses all the ways an organization shows appreciation for the time, skills, and dedication that volunteers contribute. Recognition can be formal or informal, public or private, and should be tailored to individual preferences. Formal recognition includes annual awards ceremonies, certificates and plaques, milestone awards (for hour thresholds or years of service), nominations for external volunteer awards, and letters of recommendation. Informal recognition includes verbal thank-yous, handwritten notes, social media shoutouts, small gifts or tokens of appreciation, and inclusion in organizational communications. The most effective recognition is timely, specific, and genuine - it acknowledges what the volunteer did and the impact it had. Research consistently shows that recognition is one of the top factors in volunteer retention, with volunteers who feel appreciated being significantly more likely to continue their service.', category: 'volunteer', relatedTerms: ['volunteer-retention', 'volunteer-burnout', 'volunteer-engagement', 'volunteer-coordinator'], faqQuestions: [{ question: 'What are the most effective ways to recognize volunteers?', answer: 'The most valued forms of recognition are personal thank-you notes, specific praise about their impact, public acknowledgment in newsletters or social media, awards for milestones, and simply being asked for their input and opinions.' }], keywords: ['volunteer recognition', 'volunteer appreciation', 'recognize volunteers', 'volunteer awards'] },
  { slug: 'volunteer-retention', term: 'Volunteer Retention', definition: 'The ability of an organization to keep volunteers engaged and returning over time. High retention reduces recruitment and training costs while building a more experienced and effective volunteer team.', extendedDefinition: 'Volunteer retention measures an organization\'s success in keeping volunteers actively engaged over time. The national average volunteer retention rate is approximately 65%, meaning about one-third of volunteers do not return the following year. Retention is influenced by the quality of the volunteer experience, the meaningfulness of the work, the strength of relationships with staff and other volunteers, the effectiveness of recognition programs, the flexibility of scheduling, and the overall organizational culture. Strategies for improving retention include matching volunteers to roles that align with their skills and interests, providing ongoing training and growth opportunities, maintaining regular communication, soliciting and acting on feedback, creating a welcoming and inclusive environment, and building a community among volunteers. The cost of replacing a volunteer (recruiting, screening, training) is significantly higher than the cost of retaining one, making retention one of the most important metrics for volunteer programs.', category: 'volunteer', relatedTerms: ['volunteer-burnout', 'volunteer-recognition', 'volunteer-engagement', 'volunteer-coordinator'], faqQuestions: [{ question: 'What is a good volunteer retention rate?', answer: 'The national average is approximately 65%. Retention above 75% is considered strong. Track your organization\'s rate over time and by volunteer segment to identify trends and areas for improvement.' }], keywords: ['volunteer retention', 'retain volunteers', 'volunteer retention rate', 'keep volunteers coming back'] },
  { slug: 'volunteer-scheduling', term: 'Volunteer Scheduling', definition: 'The process of assigning volunteers to specific shifts, tasks, or roles based on availability, skills, and organizational needs. Effective scheduling balances coverage requirements with volunteer preferences.', extendedDefinition: 'Volunteer scheduling is the operational process of matching available volunteers with the tasks and time slots that need to be filled. Good scheduling systems account for volunteer preferences and availability, required skills or certifications for specific roles, minimum staffing requirements for each shift or activity, fair distribution of popular and less popular assignments, and contingency plans for no-shows or last-minute cancellations. Modern volunteer management platforms offer online scheduling tools where volunteers can view available shifts, sign up for preferred times, swap shifts with other volunteers, and receive automated reminders. Self-scheduling empowers volunteers and reduces the administrative burden on coordinators. For organizations with recurring volunteer needs, creating a master schedule template that can be reused and adjusted saves significant time. Regular communication about schedule changes and consistent follow-up for unfilled shifts helps maintain adequate coverage.', category: 'volunteer', relatedTerms: ['volunteer-coordinator', 'volunteer-hours-tracking', 'volunteer-engagement', 'volunteer-retention'], faqQuestions: [{ question: 'What is the best way to schedule volunteers?', answer: 'Use an online scheduling platform that allows volunteers to self-select shifts based on their availability. Send automated reminders, allow easy shift swaps, and maintain a waitlist for popular time slots.' }], keywords: ['volunteer scheduling', 'volunteer shift management', 'volunteer schedule template', 'volunteer scheduling software'] },
]

// ── membership (26 entries, alphabetical) ─────────────────────────────────
const membership: GlossaryEntry[] = [
  { slug: 'active-member', term: 'Active Member', definition: 'A member who is current on dues, meets participation requirements, and has full voting rights and privileges within the organization.', extendedDefinition: 'An active member is someone who has met all requirements to maintain their membership in good standing, including paying current dues, completing any required participation or service hours, and not being under suspension or disciplinary action. Active members typically enjoy full privileges including voting rights, eligibility for office, access to member benefits and facilities, and participation in all organizational activities. The criteria for active membership should be clearly defined in the organization\'s bylaws. Some organizations distinguish between active members and other categories such as associate, honorary, or emeritus members who may have limited privileges. Tracking active membership counts is important for quorum calculations, financial planning, and reporting to state and national organizations.', category: 'membership', relatedTerms: ['lapsed-member', 'membership-tiers', 'member-retention', 'dues-collection'], faqQuestions: [{ question: 'What makes a member "active" vs "inactive"?', answer: 'An active member is current on dues and meets all participation requirements. An inactive member has fallen behind on dues, failed to meet participation requirements, or has not engaged with the organization for a defined period.' }], keywords: ['active member', 'active membership', 'member in good standing', 'membership status'] },
  { slug: 'annual-renewal', term: 'Annual Renewal', definition: 'The yearly process of renewing membership by paying dues and confirming continued participation. Renewal periods are critical touch points for retention and engagement.', extendedDefinition: "Annual renewal is the process by which existing members confirm their continued membership, typically by paying their annual dues. The renewal period is both a financial event and a critical engagement opportunity. Organizations that approach renewal strategically - rather than sending a single invoice - typically see meaningfully higher renewal rates. A proven renewal communication sequence starts 6-8 weeks before the renewal date with a value-reminder email (what members have gained this year, upcoming programs they would miss), followed by a formal renewal notice at 4 weeks, a reminder at 2 weeks, and a final notice in the last few days before the deadline. Offering auto-renewal is one of the most effective levers available: members who opt into automatic billing rarely lapse, because the friction of not renewing becomes higher than the friction of staying. Providing an easy online renewal link - rather than requiring a mailed check - also significantly reduces drop-off at the payment step. Staggered renewal dates (based on each member's join date) spread the administrative workload throughout the year and allow for personalized anniversary-style messaging, while a single annual renewal date simplifies administration but creates a concentrated workload spike in one month. A grace period of 30 days after the renewal deadline lets late payers retain access while staff follow up, reducing accidental lapses from members who simply forgot. After the renewal period closes, analyze which segments renewed at the lowest rates to inform next year's outreach strategy.", category: 'membership', relatedTerms: ['dues-collection', 'member-retention', 'lapsed-member', 'membership-tiers'], faqQuestions: [{ question: 'What is a good membership renewal rate?', answer: 'Industry benchmarking surveys (such as those from the American Society of Association Executives) typically report renewal rates of 80-85% for established membership organizations. Rates above 90% are considered excellent. Track your rate over time and by member segment to identify trends and at-risk groups.' }, { question: 'Should I offer a discount for early renewal?', answer: 'Early-bird renewal discounts can be effective for motivating action, particularly among price-sensitive segments. Offering a modest discount (such as waiving an annual price increase) for members who renew 4+ weeks early rewards prompt payers and reduces the last-minute rush. Be consistent year to year so members learn to expect it and plan accordingly.' }, { question: 'How do I handle members who renew late?', answer: "Offer a grace period of 30 days after the renewal deadline during which lapsed members can renew without a reinstatement fee. After the grace period, consider a small reinstatement fee to cover the administrative cost of reactivation, but keep it modest - the goal is to recover members, not punish them. Reach out personally to high-value or long-tenured members who haven't renewed, as a brief personal call or message often recovers members who simply forgot." }], keywords: ['membership renewal', 'annual renewal', 'membership renewal rate', 'renew membership', 'membership renewal best practices', 'club membership renewal process', 'how to increase renewal rates'] },
  { slug: 'bulk-operations', term: 'Bulk Operations', definition: 'Administrative actions performed on multiple member records simultaneously, such as updating statuses, sending communications, or adjusting dues. Bulk operations save time when managing large memberships.', extendedDefinition: 'Bulk operations allow administrators to perform actions on groups of members at once rather than one at a time. Common bulk operations include updating membership statuses (e.g., marking all expired members as lapsed), sending mass communications (renewal reminders, event announcements, newsletters), adjusting dues or fees across a membership tier, importing or exporting member data, generating bulk reports or labels, and applying tags or categories to groups of members. Member management software that supports bulk operations significantly reduces administrative time, especially for organizations with hundreds or thousands of members. When performing bulk operations, best practices include previewing the affected records before executing, maintaining backups, sending test communications before mass sends, and documenting what changes were made and when for audit purposes.', category: 'membership', relatedTerms: ['member-database', 'member-import-export', 'membership-tiers', 'dues-collection'], faqQuestions: [{ question: 'What are common bulk operations in member management?', answer: 'Common operations include mass status updates, bulk email sends, dues adjustments across tiers, data imports/exports, batch tag assignments, and generating mailing labels or reports for groups of members.' }], keywords: ['bulk operations', 'bulk member update', 'mass member operations', 'batch member management'] },
  { slug: 'churn-rate', term: 'Churn Rate', definition: 'The percentage of members who leave or do not renew their membership during a given period. A high churn rate indicates problems with member satisfaction, value proposition, or engagement.', extendedDefinition: 'Churn rate (also called attrition rate) is the inverse of retention rate and measures the percentage of members who discontinue their membership over a specific period. It is calculated by dividing the number of members lost during a period by the total number of members at the beginning of that period. For example, if an organization starts the year with 500 members and loses 75, the annual churn rate is 15%. Understanding churn is essential for financial planning and organizational sustainability - every lost member represents lost dues revenue and requires investment to replace through recruitment. Analyzing churn by member segment (new vs. long-term, different tiers, demographics) can reveal patterns and help target retention efforts. Common causes of churn include perceived lack of value, life changes (relocation, schedule changes), financial constraints, poor experiences, and better alternatives. Reducing churn by even a few percentage points can significantly impact revenue and organizational stability.', category: 'membership', relatedTerms: ['member-retention', 'lapsed-member', 'annual-renewal', 'member-engagement'], faqQuestions: [{ question: 'What is an acceptable churn rate for a membership organization?', answer: 'Annual churn rates of 10-20% are common for membership organizations. Rates below 10% indicate strong retention. First-year member churn is typically higher (25-40%), making early engagement critical.' }], keywords: ['membership churn rate', 'member attrition', 'churn rate calculation', 'reduce membership churn'] },
  { slug: 'custom-fields', term: 'Custom Fields', definition: 'User-defined data fields added to member profiles to capture organization-specific information beyond standard fields like name, email, and phone number.', extendedDefinition: 'Custom fields allow organizations to tailor their member database to capture information unique to their needs. While standard fields cover basics like contact information and membership status, custom fields can capture anything relevant to the organization: skill sets and areas of expertise, committee assignments and preferences, certification or license information, dietary restrictions for events, t-shirt sizes, emergency contact information, preferred volunteer activities, professional background, and any other data points important to the organization. Good member management software allows administrators to create custom fields of various types (text, dropdown, date, checkbox, multi-select) and control visibility and editing permissions. Custom fields should be used judiciously - collecting too much data can make the registration process cumbersome and raise privacy concerns. Only collect information that the organization will actually use.', category: 'membership', relatedTerms: ['member-database', 'member-directory', 'membership-tiers', 'member-import-export'], faqQuestions: [{ question: 'What custom fields should a club add to member profiles?', answer: 'Focus on fields you will actually use: skills and interests (for committee placement), dietary restrictions (for events), emergency contacts, communication preferences, and any certifications or requirements specific to your organization.' }], keywords: ['custom member fields', 'member profile fields', 'custom data fields', 'membership database fields'] },
  { slug: 'dues-collection', term: 'Dues Collection', definition: 'The process of billing and receiving membership fees from members. Modern dues collection uses automated recurring payments, online payment portals, and reminder systems to maximize collection rates.', extendedDefinition: 'Dues collection is the financial backbone of most membership organizations and includes the entire process from invoicing to payment receipt to reconciliation. Effective dues collection systems offer multiple payment methods (credit card, ACH bank transfer, check, cash), automated recurring payment options that reduce friction, timely invoicing with clear payment deadlines, automated reminder sequences for overdue payments, grace periods before membership privileges are suspended, easy self-service payment through member portals, and clear receipts for tax purposes. Automating dues collection through a platform that processes recurring payments significantly improves collection rates and reduces administrative burden. Key metrics to track include collection rate (percentage of billed dues actually collected), average days to payment, percentage of members on auto-pay, and outstanding receivables. Organizations should also have clear policies about late fees, grace periods, and what happens to benefits when dues are not paid.', category: 'membership', relatedTerms: ['annual-renewal', 'active-member', 'lapsed-member', 'membership-tiers'], faqQuestions: [{ question: 'How can organizations improve their dues collection rate?', answer: 'Offer auto-pay enrollment, accept multiple payment methods, send timely reminders, make online payment easy, provide clear value for dues paid, and offer flexible payment plans for members who need them.' }], keywords: ['dues collection', 'membership dues', 'collect dues online', 'automated dues collection'] },
  { slug: 'lapsed-member', term: 'Lapsed Member', definition: 'A former member whose membership has expired due to non-renewal of dues or failure to meet membership requirements. Lapsed members are often the easiest group to re-engage and recruit back.', extendedDefinition: "A lapsed member is someone who was previously in good standing but whose membership has expired, typically because they did not renew their dues by the deadline (including any grace period). Lapsed members represent an important recovery opportunity for organizations because they already know and have engaged with the club - re-engagement is far less expensive than acquiring a brand-new member. A structured win-back sequence often works better than a single re-engagement email. A typical sequence runs over 90 days: an immediate lapse notification (friendly, not scolding), a 30-day follow-up that highlights new programs or events they are missing, a 60-day outreach that offers a reinstatement incentive such as waived fees or a discounted first-year return rate, and a final 90-day message that closes the loop and asks whether they would like to be removed from communications. Personalizing these messages - referencing events they attended or committees they participated in - substantially improves response rates compared to generic form letters. Organizations should also segment lapsed members by their original reason for leaving (cost, relocation, time constraints, dissatisfaction) where that data is available, and tailor messages accordingly. Tracking your annual lapse rate - the percentage of renewing members who let their membership expire each year - is a core health metric. Most community clubs see lapse rates somewhere between 10-25% annually, though this varies significantly by member tenure, engagement level, and the value the club delivers. Proactive intervention with at-risk members (those who have attended no events in 6+ months and haven't engaged with recent communications) before they lapse is always more effective than recovery campaigns after the fact.", category: 'membership', relatedTerms: ['member-retention', 'churn-rate', 'annual-renewal', 'active-member'], faqQuestions: [{ question: 'How should organizations try to win back lapsed members?', answer: 'Send a series of personalized re-engagement emails over 90 days, offer a reinstatement incentive, highlight what is new since they left, ask why they left and address their concerns, and make the rejoin process simple.' }, { question: 'How long should you wait before removing a lapsed member from your database?', answer: "Most organizations retain lapsed member records for at least 2-3 years before archiving them. Former members may return after a life change (relocation, schedule shift, renewed interest), and their history is valuable for personalizing re-engagement. After 2-3 years of no response to win-back outreach, move them to an inactive archive rather than deleting the record entirely." }, { question: 'What is a typical membership lapse rate for community clubs?', answer: "Lapse rates vary widely by organization type and how actively members are engaged, but many community and hobby clubs see annual lapse rates somewhere in the 10-25% range. Clubs with strong programming, regular communications, and high perceived value tend to have rates at the lower end. Tracking your own year-over-year trend is more actionable than benchmarking against industry averages." }], keywords: ['lapsed member', 'expired membership', 'win back lapsed members', 'membership lapse', 'membership lapse rate', 're-engage former members', 'membership win-back campaign'] },
  { slug: 'member-database', term: 'Member Database', definition: 'A centralized system for storing, organizing, and managing all member information including contact details, membership status, payment history, event attendance, and communication records.', extendedDefinition: 'A member database is the central repository for all information about an organization\'s members. It serves as the single source of truth for membership status, contact information, engagement history, and administrative records. A well-maintained member database includes personal information (name, address, phone, email), membership details (join date, tier, status, renewal date), financial records (dues payments, donations, purchase history), engagement data (event attendance, volunteer hours, committee involvement), communication history (emails sent, preferences, opt-outs), and custom fields specific to the organization. The database should be accessible to authorized administrators, searchable and filterable, regularly backed up, and compliant with privacy regulations. Modern member management platforms provide cloud-based databases with role-based access controls, import/export capabilities, and integration with communication and payment tools.', category: 'membership', relatedTerms: ['custom-fields', 'member-directory', 'member-import-export', 'member-segmentation'], faqQuestions: [{ question: 'Should a club use a spreadsheet or a member management platform?', answer: 'Small clubs (under 50 members) may manage with a spreadsheet, but as organizations grow, a dedicated platform provides better security, multi-user access, automated renewals, payment processing, and communication tools that spreadsheets cannot match.' }], keywords: ['member database', 'membership database', 'member management system', 'member CRM'] },
  { slug: 'member-directory', term: 'Member Directory', definition: 'A searchable listing of organization members that facilitates networking and communication. Directories typically include contact information, roles, and other details that members choose to share.', extendedDefinition: 'A member directory is a listing of members that helps facilitate connections and communication within the organization. Directories can be printed, published on a website, or accessed through a mobile app. Modern digital directories are searchable and filterable, allowing members to find others by name, location, skills, interests, or committee involvement. Privacy is a critical consideration - organizations should let members control what information is visible in the directory and comply with applicable privacy laws. Options include full opt-out from the directory, selective field visibility (show name and role but hide phone number), and public vs. member-only access. A well-maintained directory adds significant value to membership by facilitating networking, mentorship, business referrals, and social connections. Organizations should update the directory regularly and make it easily accessible to members while protecting it from unauthorized use.', category: 'membership', relatedTerms: ['member-database', 'member-portal', 'custom-fields', 'active-member'], faqQuestions: [{ question: 'How should member directory privacy be handled?', answer: 'Let members choose what information to display and whether to appear in the directory at all. Require login to access the directory, prohibit commercial use, and comply with privacy laws. Regularly remind members to update their preferences.' }], keywords: ['member directory', 'membership directory', 'online member directory', 'searchable member directory'] },
  { slug: 'member-engagement', term: 'Member Engagement', definition: 'The level of active participation and emotional connection a member has with an organization. Engaged members attend events, volunteer, participate in programs, and advocate for the organization.', extendedDefinition: 'Member engagement measures the depth and breadth of a member\'s involvement with an organization beyond simply paying dues. Engagement is a strong predictor of renewal - members who are actively engaged are significantly more likely to renew their membership. Key engagement indicators include event attendance frequency, committee or volunteer involvement, response to communications, use of member benefits and resources, participation in online communities or forums, referral of new members, and feedback and suggestions offered. Organizations can measure engagement through an engagement score that combines multiple data points into a single metric. This score can be used to identify highly engaged members (potential leaders), at-risk members (low engagement), and trends over time. Strategies for increasing engagement include personalized onboarding, regular and valuable communications, diverse programming that appeals to different interests, peer connections and mentoring, and leadership opportunities at various commitment levels.', category: 'membership', relatedTerms: ['member-retention', 'active-member', 'member-onboarding', 'churn-rate'], faqQuestions: [{ question: 'How do you measure member engagement?', answer: 'Create an engagement score combining event attendance, volunteer hours, committee participation, email interaction, online community activity, and other measurable touchpoints. Track scores over time and by segment to identify trends and at-risk members.' }], keywords: ['member engagement', 'membership engagement', 'engage members', 'member engagement score'] },
  { slug: 'member-import-export', term: 'Member Import/Export', definition: 'The ability to transfer member data into and out of a management system, typically using CSV or Excel files. Import/export functionality is essential for data migration, reporting, and integration with other tools.', extendedDefinition: 'Member import and export capabilities allow organizations to move data between systems, create custom reports, and migrate to new platforms. Import features enable organizations to load existing member data from spreadsheets or other databases, add new members in bulk, and update existing records en masse. Export features allow generating mailing lists, creating custom reports, backing up data, and sharing information with other systems. Best practices include mapping fields carefully during import to ensure data goes into the correct columns, cleaning and deduplicating data before import, backing up existing data before any bulk import, testing imports with a small sample before processing the full dataset, and maintaining a consistent data format for ongoing exchanges. Regular exports also serve as data backups and can be used for analysis in tools like Excel or Google Sheets.', category: 'membership', relatedTerms: ['member-database', 'bulk-operations', 'custom-fields', 'member-segmentation'], faqQuestions: [{ question: 'What format should member data be in for import?', answer: 'Most member management platforms accept CSV (comma-separated values) files. Ensure your data is clean: one record per row, consistent formatting, no merged cells, and column headers matching the platform\'s field names.' }], keywords: ['member data import', 'export member data', 'member data migration', 'CSV member import'] },
  { slug: 'member-onboarding', term: 'Member Onboarding', definition: 'The process of welcoming and orienting new members to an organization, introducing them to resources, programs, and fellow members. Effective onboarding increases engagement and reduces early attrition.', extendedDefinition: 'Member onboarding is the structured process of integrating new members into the organization and helping them realize the full value of their membership. Research shows that the first 90 days of membership are critical - members who are not engaged within this period are significantly more likely to lapse. An effective onboarding program includes an immediate welcome communication upon joining, a new member orientation (in-person or virtual), introduction to key contacts, staff, and fellow members, a guide to available resources, benefits, and programs, an invitation to upcoming events tailored to their interests, a follow-up check-in at 30, 60, and 90 days, and assignment of a buddy or mentor from the existing membership. The onboarding experience should be personalized based on the member\'s interests and what drew them to the organization. Track onboarding completion and early engagement metrics to continuously improve the process.', category: 'membership', relatedTerms: ['member-retention', 'member-engagement', 'active-member', 'membership-tiers'], faqQuestions: [{ question: 'What should be included in a new member welcome packet?', answer: 'Include a welcome letter, membership card, overview of benefits and programs, upcoming events calendar, key contact information, instructions for accessing online resources and the member portal, and information about committees and volunteer opportunities.' }], keywords: ['member onboarding', 'new member orientation', 'new member welcome', 'membership onboarding process'] },
  { slug: 'member-portal', term: 'Member Portal', definition: 'A secure online area where members can manage their membership, update personal information, pay dues, register for events, and access member-only resources and content.', extendedDefinition: "A member portal is a password-protected section of an organization's website or app that provides members with self-service access to their membership information and organizational resources. Core portal features include profile management (updating contact info, preferences, and privacy settings), dues payment and billing history, event registration and calendar, member directory access, document library (minutes, bylaws, newsletters), communication preferences and opt-outs, committee and volunteer sign-ups, and digital membership card. The portal reduces administrative burden significantly: when members can update their own contact details, pay dues online, and register for events without emailing the secretary, admins spend less time on data entry and fielding routine questions. For small clubs with volunteer administrators, this time saving is especially meaningful - freeing up hours each month for programs and member engagement rather than inbox management. For the portal to be effective, it must be genuinely easy to use on a smartphone, since many members will access it on mobile rather than a desktop. A confusing login process, too many required fields, or a portal that is not optimized for small screens will result in low adoption and members defaulting to emailing the admin anyway. Single sign-on (SSO) integration and mobile app access improve adoption further. Organizations should promote portal features actively - through welcome emails for new members, and reminders during renewal season - rather than assuming members will discover features on their own. Start with the highest-value features (dues payment, event registration) and add additional content progressively as members build the habit of using the portal.", category: 'membership', relatedTerms: ['member-database', 'member-directory', 'dues-collection', 'member-engagement'], faqQuestions: [{ question: 'What features are most important in a member portal?', answer: 'The top features members value are easy dues payment, event registration, member directory access, personal profile management, and access to member-only content and resources. Mobile compatibility is increasingly essential.' }, { question: 'Do members actually use member portals regularly?', answer: "Adoption varies widely based on how useful the portal is and how actively the organization promotes it. Portals with high adoption typically offer something members genuinely need - most often online dues payment and event registration. Portals that only mirror information already available elsewhere see much lower usage. Sending members to the portal for their first renewal payment is one of the most effective ways to establish the habit." }, { question: 'What should a member portal include for a small club?', answer: "For a small club, prioritize these essentials: online dues payment (the single biggest adoption driver), event calendar with registration, personal profile editing, and a document library for minutes and governing documents. A member directory is a high-value addition once you have privacy consent sorted. Keep it simple - a portal with five features that members actually use beats a complex portal that overwhelms them." }], keywords: ['member portal', 'membership portal', 'online member portal', 'member self-service portal', 'online membership portal', 'member self-service software', 'club member login portal'] },
  { slug: 'member-retention', term: 'Member Retention', definition: 'The ability of an organization to keep members enrolled and engaged over time. Retention rate is one of the most important metrics for organizational health, as retaining members costs far less than acquiring new ones.', extendedDefinition: 'Member retention measures the percentage of members who renew or maintain their membership from one period to the next. It is widely considered the most important membership metric because retaining existing members is 5-10 times less expensive than recruiting new ones, long-term members contribute more through dues, donations, volunteering, and referrals, and high retention creates organizational stability and institutional knowledge. Key factors influencing retention include perceived value relative to dues cost, quality and relevance of programs and events, strength of social connections within the organization, quality of communication and engagement, ease of administrative processes (renewal, event registration), and responsiveness to member needs and feedback. Organizations should segment their retention analysis by member tenure, tier, engagement level, and demographics to identify at-risk groups and develop targeted retention strategies.', category: 'membership', relatedTerms: ['churn-rate', 'lapsed-member', 'member-engagement', 'annual-renewal'], faqQuestions: [{ question: 'How can organizations improve member retention?', answer: 'Focus on delivering clear value, building community connections, providing excellent onboarding, communicating regularly, making it easy to engage (events, volunteering, committees), asking for and acting on feedback, and intervening early when engagement drops.' }], keywords: ['member retention', 'membership retention', 'retain members', 'member retention strategies'] },
  { slug: 'member-segmentation', term: 'Member Segmentation', definition: 'The practice of dividing a membership into groups based on shared characteristics such as demographics, interests, engagement level, or membership tier for more targeted communications and programming.', extendedDefinition: "Member segmentation allows organizations to tailor their communications, programming, and outreach to different groups within their membership. Rather than sending the same message to everyone, segmented communications are more relevant and effective. Common segmentation criteria include membership tier or type, tenure (new, mid-career, long-term), engagement level (highly active, moderately engaged, at-risk), demographics (age, location, profession), interests and preferences, committee or volunteer involvement, event attendance patterns, and communication preferences. Some of the most actionable segments for club admins include: new members in their first 90 days (who benefit from onboarding communications and a warm welcome), members who haven't attended any event in the past 6 months (at-risk of lapsing and candidates for re-engagement outreach), members approaching their renewal date in the next 30 days (who need timely renewal reminders), and long-tenured members with 5+ years (who may respond well to recognition and leadership opportunities). Segmentation enables organizations to send renewal reminders tailored to each group's situation, create programming that appeals to different member interests, identify at-risk members for proactive personal outreach before they lapse, and allocate volunteer time for relationship-building where it will have the most impact. The quality of segmentation depends directly on the quality of data in the member database. Organizations that collect and maintain accurate join dates, event attendance records, and interest information can segment with precision; organizations with sparse or outdated records must start by improving data collection before segmentation becomes meaningful.", category: 'membership', relatedTerms: ['member-database', 'member-engagement', 'custom-fields', 'bulk-operations'], faqQuestions: [{ question: 'What are the most useful member segments?', answer: 'Start with engagement level (active vs. at-risk), tenure (new vs. established), and membership tier. These three dimensions cover the most common communication and programming needs.' }, { question: 'How do you segment members without complex software?', answer: "You can segment members effectively with a well-maintained spreadsheet if your membership is small. Create columns for join date, last event attended, membership tier, and interests, then filter or sort by these fields when preparing communications. As your membership grows past 50-100 members, a dedicated membership management tool makes segmentation far more practical and saves significant admin time." }, { question: 'What data do I need to segment members effectively?', answer: "The three most valuable data points for segmentation are: (1) join date - to identify new members and tenure cohorts, (2) event attendance history - to identify active vs. at-risk members, and (3) renewal date - to time renewal communications precisely. Secondary data like interests, location, and membership tier unlock more sophisticated segments once the basics are in place." }], keywords: ['member segmentation', 'membership segmentation', 'segment members', 'targeted member communications', 'how to segment club members', 'membership database segmentation', 'targeted member outreach'] },
  { slug: 'membership-tiers', term: 'Membership Tiers', definition: 'Multiple levels of membership with different pricing, benefits, and privileges. Tiered memberships allow organizations to serve diverse needs and create upgrade paths for increased engagement.', extendedDefinition: 'Membership tiers (also called membership levels or categories) allow organizations to offer different packages of benefits at different price points. A typical tiered structure might include a basic or introductory level with essential benefits at a lower price, a standard or professional level with full benefits at the regular price, a premium or patron level with enhanced benefits and recognition at a higher price, and special categories like student, senior, or family rates. Tiered memberships benefit organizations by maximizing revenue from members willing to pay more, providing an accessible entry point for price-sensitive members, creating a clear upgrade path that increases lifetime member value, and allowing targeted programming for different member needs. When designing tiers, ensure each level provides clear, distinct value that justifies the price difference. The most popular tier should be the one that generates the best balance of revenue and member satisfaction, often positioned as the "recommended" option.', category: 'membership', relatedTerms: ['dues-collection', 'active-member', 'member-retention', 'annual-renewal'], faqQuestions: [{ question: 'How many membership tiers should an organization offer?', answer: 'Most organizations find 2-4 tiers optimal. Too few limits revenue potential, while too many creates confusion. Ensure each tier has clearly distinct value and pricing. Three tiers (basic, standard, premium) is the most common structure.' }], keywords: ['membership tiers', 'membership levels', 'tiered membership', 'membership tier structure'] },
]

// ── financial (25 entries, alphabetical) ──────────────────────────────────
const financial: GlossaryEntry[] = [
  { slug: 'ach-payment', term: 'ACH Payment', definition: 'An electronic bank-to-bank transfer processed through the Automated Clearing House network. ACH payments are commonly used for recurring dues and have lower processing fees than credit cards.', extendedDefinition: 'ACH (Automated Clearing House) payments are electronic transfers between bank accounts that bypass the credit card networks. For membership organizations, ACH is attractive because processing fees are significantly lower than credit card fees (typically a flat fee of $0.20-$0.50 per transaction versus 2.5-3.5% for credit cards). ACH is ideal for recurring payments like monthly or annual dues because it does not expire like credit cards, reducing payment failures. However, ACH payments take longer to process (1-3 business days versus instant for credit cards), have a longer dispute window, and require the member to provide their bank routing and account numbers. Organizations can offer ACH as an alternative to credit card payments to reduce processing costs while giving members a convenient electronic payment option.', category: 'financial', relatedTerms: ['payment-gateway', 'recurring-payment', 'dues-collection', 'payment-processor'], faqQuestions: [{ question: 'Is ACH cheaper than credit card processing?', answer: 'Yes, significantly. ACH fees are typically a flat $0.20-$0.50 per transaction, while credit card processing fees are usually 2.5-3.5% of the transaction amount. For a $200 annual dues payment, ACH saves $4.50-$6.50 per transaction.' }], keywords: ['ACH payment', 'ACH transfer', 'automated clearing house', 'ACH vs credit card'] },
  { slug: 'annual-budget', term: 'Annual Budget', definition: 'A financial plan that estimates an organization\'s income and expenses for the coming fiscal year. The budget guides spending decisions and provides a benchmark for measuring financial performance.', extendedDefinition: 'An annual budget is the financial roadmap for an organization\'s fiscal year. It projects all anticipated revenue sources (dues, events, fundraising, sponsorships, investment income) and all planned expenses (programs, staffing, facilities, communications, insurance, supplies). The budget should be developed collaboratively by the treasurer, finance committee, and executive leadership, then approved by the board of directors. Best practices include basing projections on historical data and realistic assumptions, building in a contingency reserve of 5-10%, reviewing and comparing actual results to budget quarterly, adjusting projections mid-year if significant variances occur, and maintaining a reserve fund covering 3-6 months of operating expenses. The budget serves multiple purposes: it is a planning tool, a communication document that shows members how dues are used, a control mechanism for spending, and a performance evaluation tool for organizational leaders.', category: 'financial', relatedTerms: ['treasurers-report', 'financial-audit', 'restricted-funds', 'unrestricted-funds'], faqQuestions: [{ question: 'How should a club create its annual budget?', answer: 'Review the previous year\'s actual income and expenses, adjust for known changes, get input from committee chairs on their needs, build in a 5-10% contingency, and present the draft to the board for review and approval.' }], keywords: ['annual budget', 'nonprofit budget', 'organization budget', 'annual budget template'] },
  { slug: 'assessment', term: 'Assessment', definition: 'A mandatory charge levied on members beyond regular dues to fund a specific expense or project. Assessments are commonly used by HOAs and clubs when reserves are insufficient to cover unexpected costs.', extendedDefinition: 'An assessment is a special charge imposed on members, typically to cover costs that are not included in the regular budget. Assessments are most common in homeowner associations (HOAs) and condominium associations, where they fund major repairs, legal expenses, or capital improvements not covered by regular dues or reserve funds. There are two types: special assessments (one-time charges for specific needs) and regular assessments (ongoing charges that supplement dues). The authority to levy assessments, the approval process required (often a membership vote), and any limitations on assessment amounts should be defined in the organization\'s governing documents. Assessments can create member dissatisfaction, so organizations should communicate clearly about why the assessment is needed, how the amount was determined, what alternatives were considered, and when and how payment is expected. Offering payment plans can help ease the financial burden on members.', category: 'financial', relatedTerms: ['dues-collection', 'annual-budget', 'reserve-fund', 'hoa-dues'], faqQuestions: [{ question: 'Can an HOA levy a special assessment without a member vote?', answer: 'It depends on the governing documents and state law. Many HOA bylaws require member approval for assessments above a certain threshold. State laws also vary on assessment authority. Check your CC&Rs and applicable state statutes.' }], keywords: ['special assessment', 'HOA assessment', 'member assessment', 'special assessment levy'] },
  { slug: 'financial-transparency', term: 'Financial Transparency', definition: 'The practice of openly sharing an organization\'s financial information with members and stakeholders. Transparency builds trust, accountability, and member confidence in organizational leadership.', extendedDefinition: 'Financial transparency means providing members and stakeholders with clear, accessible, and timely information about how the organization\'s money is received and spent. Transparent practices include presenting regular treasurer\'s reports at meetings, publishing annual financial statements, making budgets available to members, disclosing executive compensation, sharing audit results, providing clear breakdowns of how dues are used, and making Form 990 and other required filings publicly accessible. Transparency is not just about compliance - it is a trust-building strategy that increases member satisfaction, encourages donations, and supports good governance. Organizations should strike a balance between transparency and appropriate confidentiality (such as protecting individual salary data or sensitive business information). Financial reports should be presented in language that non-financial members can understand, with clear explanations of significant numbers and trends.', category: 'financial', relatedTerms: ['treasurers-report', 'annual-budget', 'financial-audit', 'form-990'], faqQuestions: [{ question: 'What financial information should be shared with members?', answer: 'At minimum: the annual budget, regular treasurer\'s reports, annual financial statements, and audit results. Many organizations also share a breakdown of how dues are used and make Form 990 available upon request.' }], keywords: ['financial transparency', 'nonprofit transparency', 'financial accountability', 'open financial reporting'] },
  { slug: 'fiscal-year', term: 'Fiscal Year', definition: 'A 12-month period used for accounting, budgeting, and financial reporting. A fiscal year may or may not align with the calendar year, depending on the organization\'s preference and industry norms.', extendedDefinition: 'A fiscal year (also called a financial year) is the 12-month period an organization uses as its accounting and tax reporting cycle. While many organizations use the calendar year (January 1 to December 31), others choose a fiscal year that aligns with their operational cycle. For example, a school-related organization might use July 1 to June 30, or a sports league might use September 1 to August 31. The choice of fiscal year affects when budgets are prepared, when Form 990 is due, when annual meetings are held, and when membership renewals occur. To change a fiscal year, organizations typically need board approval and must notify the IRS by filing a short-period return. The fiscal year should be specified in the bylaws. All financial planning, reporting, and tax filing is based on the fiscal year, so it is important that all stakeholders understand which 12-month period the organization uses.', category: 'financial', relatedTerms: ['annual-budget', 'financial-audit', 'form-990', 'treasurers-report'], faqQuestions: [{ question: 'Should a club use a calendar year or a different fiscal year?', answer: 'The calendar year is simplest and most common. However, if your organization\'s activities follow a specific cycle (like a school year or sports season), aligning the fiscal year with that cycle can make budgeting and reporting more intuitive.' }], keywords: ['fiscal year', 'financial year', 'fiscal year vs calendar year', 'nonprofit fiscal year'] },
  { slug: 'grant', term: 'Grant', definition: 'A financial award given by a foundation, corporation, or government agency to a nonprofit organization to support a specific program, project, or operational need. Grants do not require repayment.', extendedDefinition: 'Grants are a significant funding source for many nonprofit organizations. They are awarded by foundations, corporations, and government agencies based on applications that demonstrate alignment with the funder\'s mission and priorities. The grant process typically involves identifying potential funders whose interests match your organization\'s work, submitting a proposal that describes the project, its budget, expected outcomes, and the organization\'s capacity, and if awarded, implementing the project according to the grant terms and providing required reports. Grants may be restricted (for a specific purpose) or unrestricted (for general operations). Competition for grants can be intense, so organizations should invest time in building relationships with funders, writing compelling proposals, and demonstrating measurable outcomes from previous grants. Key resources for finding grants include the Foundation Directory Online, Grants.gov for federal grants, and local community foundation listings.', category: 'financial', relatedTerms: ['restricted-funds', 'fundraising', 'annual-fund', 'capital-campaign'], faqQuestions: [{ question: 'How does an organization find grants to apply for?', answer: 'Research funding databases like Foundation Directory Online and Grants.gov, check local community foundations, network with other nonprofits, subscribe to grant alert services, and build relationships with funders before applying.' }], keywords: ['nonprofit grant', 'grant funding', 'apply for grants', 'grant writing'] },
  { slug: 'hoa-dues', term: 'HOA Dues', definition: 'Regular fees paid by homeowners to their homeowner association for maintenance of common areas, amenities, and shared services. HOA dues fund landscaping, insurance, utilities, and reserve contributions.', extendedDefinition: 'HOA (Homeowner Association) dues are the regular assessments that homeowners pay to their association to fund the maintenance and operation of common areas and shared amenities. HOA dues typically cover landscaping and grounds maintenance, common area utilities, insurance for common elements, management company fees, reserve fund contributions, amenity maintenance (pools, clubhouses, gyms), security and gate operations, and administrative expenses. Dues amounts are determined by the annual budget and divided among homeowners, often equally or proportionally based on property size or unit type. The HOA board sets the dues amount, usually with an annual increase to keep pace with inflation and growing costs. Failure to pay HOA dues can result in late fees, suspension of amenity access, and in some states, a lien on the property. HOA financial management requires careful budgeting, adequate reserve funding, and transparent financial reporting to homeowners.', category: 'financial', relatedTerms: ['assessment', 'reserve-fund', 'annual-budget', 'dues-collection'], faqQuestions: [{ question: 'What happens if a homeowner does not pay HOA dues?', answer: 'Consequences escalate from late fees to suspension of amenity access, and can ultimately include placing a lien on the property and, in some states, foreclosure. The specific process and timeline depend on the CC&Rs and state law.' }], keywords: ['HOA dues', 'homeowner association fees', 'HOA fees', 'HOA assessment'] },
  { slug: 'merchant-account', term: 'Merchant Account', definition: 'A type of bank account that enables organizations to accept credit card and debit card payments. Merchant accounts are required for processing card payments for dues, events, and donations.', extendedDefinition: 'A merchant account is a business bank account that allows an organization to accept and process electronic payment card transactions. When a member pays dues or registers for an event with a credit or debit card, the payment flows through the merchant account before being deposited into the organization\'s regular bank account. Modern payment processing has evolved significantly - many organizations now use payment service providers like Stripe, Square, or PayPal that bundle merchant account functionality with payment gateway and processing services, eliminating the need for a separate merchant account. Key considerations when choosing a payment processing solution include transaction fees and monthly costs, supported payment methods, integration with member management software, fund disbursement timing, security and PCI compliance, and reporting capabilities.', category: 'financial', relatedTerms: ['payment-gateway', 'payment-processor', 'dues-collection', 'ach-payment'], faqQuestions: [{ question: 'Does a nonprofit need a merchant account to accept credit cards?', answer: 'You need payment processing capability, but not necessarily a traditional merchant account. Payment service providers like Stripe handle merchant account functionality, payment gateway, and processing in one integrated service.' }], keywords: ['merchant account', 'accept credit cards', 'nonprofit payment processing', 'merchant account nonprofit'] },
  { slug: 'payment-gateway', term: 'Payment Gateway', definition: 'Software that securely transmits payment information between a website or app and the payment processor. The gateway encrypts sensitive data and authorizes transactions in real time.', extendedDefinition: 'A payment gateway is the technology that securely connects an organization\'s website or app to the financial networks that process credit card and electronic payments. When a member enters their payment information online, the gateway encrypts the data, sends it to the payment processor for authorization, receives the approval or decline response, and communicates the result back to the website. For member management, the payment gateway enables online dues payment, event registration with payment, donation processing, and automatic recurring billing. Key features to look for include PCI DSS compliance, support for multiple payment methods, fraud detection tools, tokenization for secure storage of payment information, and seamless integration with your member management platform. Popular payment gateways include Stripe, Authorize.Net, and Braintree. Many modern platforms like Stripe combine gateway and processing functionality.', category: 'financial', relatedTerms: ['payment-processor', 'merchant-account', 'recurring-payment', 'ach-payment'], faqQuestions: [{ question: 'What is the difference between a payment gateway and a payment processor?', answer: 'A payment gateway is the technology that securely transmits payment data (like an encrypted tunnel). A payment processor is the service that actually moves funds between banks and card networks. Many modern services like Stripe combine both functions.' }], keywords: ['payment gateway', 'online payment gateway', 'payment gateway meaning', 'payment gateway for nonprofits'] },
  { slug: 'payment-processor', term: 'Payment Processor', definition: 'A company that handles the transfer of funds between a buyer\'s bank and a seller\'s bank when a payment is made. Payment processors work with card networks like Visa and Mastercard to authorize and settle transactions.', extendedDefinition: 'A payment processor is the intermediary that manages the flow of funds during a credit card or electronic payment transaction. The processor communicates between the merchant (organization), the card network (Visa, Mastercard, etc.), and the banks (the member\'s issuing bank and the organization\'s acquiring bank) to authorize, settle, and fund transactions. For membership organizations, the payment processor handles all the back-end financial mechanics of dues payments, event registrations, and donations. Key factors when choosing a processor include fee structure (flat rate vs. interchange-plus), monthly minimums and statement fees, contract terms and cancellation policies, settlement timing, chargeback handling, customer support quality, and integration with your management software. Popular processors for nonprofits and membership organizations include Stripe, PayPal, and Square, which offer competitive rates and easy integration.', category: 'financial', relatedTerms: ['payment-gateway', 'merchant-account', 'ach-payment', 'recurring-payment'], faqQuestions: [{ question: 'What fees do payment processors charge?', answer: 'Typical fees are 2.2-2.9% plus $0.20-$0.30 per transaction for credit cards. Some processors offer lower rates for nonprofits. ACH processing is usually a flat fee of $0.20-$0.50 per transaction.' }], keywords: ['payment processor', 'credit card processor', 'payment processing fees', 'nonprofit payment processor'] },
  { slug: 'recurring-payment', term: 'Recurring Payment', definition: 'An automatic payment that is charged to a member\'s payment method at regular intervals, such as monthly or annually. Recurring payments simplify dues collection and improve cash flow predictability.', extendedDefinition: 'Recurring payments (also called auto-pay or automatic billing) are scheduled transactions that automatically charge a member\'s credit card or bank account at predetermined intervals. For membership organizations, recurring payments offer significant benefits: improved cash flow predictability, reduced administrative time spent on invoicing and collections, higher collection rates (fewer missed payments), reduced involuntary churn from expired credit cards, and a smoother financial experience for members. When implementing recurring payments, organizations should clearly communicate what will be charged and when, make it easy for members to update payment methods, send advance notifications before charges, provide simple cancellation procedures, and have a process for handling failed payments (dunning). Failed payment recovery is especially important - implementing automatic retry logic and notifications for expired or declined cards can recover a significant percentage of otherwise lost revenue.', category: 'financial', relatedTerms: ['dues-collection', 'ach-payment', 'payment-gateway', 'payment-processor'], faqQuestions: [{ question: 'How much can recurring payments improve collection rates?', answer: 'Organizations that implement recurring payments typically see collection rates improve by 10-20 percentage points. Auto-pay enrollment rates of 60-80% are achievable with proper setup and encouragement.' }], keywords: ['recurring payment', 'auto pay', 'automatic dues payment', 'recurring billing'] },
  { slug: 'reserve-fund', term: 'Reserve Fund', definition: 'Money set aside by an organization for future capital expenditures, emergencies, or unexpected expenses. Reserve funds provide financial stability and reduce the need for special assessments.', extendedDefinition: 'A reserve fund is a savings account or investment portfolio maintained by an organization to cover future large expenses and unforeseen financial needs. For HOAs, reserve funds are especially important for replacing major common elements like roofs, parking lots, elevators, and mechanical systems. For clubs and nonprofits, reserves provide a cushion against revenue shortfalls, unexpected expenses, and economic downturns. Best practices for reserve fund management include conducting a reserve study (for HOAs) to determine how much is needed, contributing to reserves regularly through annual budget allocations, maintaining reserves in interest-bearing accounts or conservative investments, establishing a reserve policy that defines the target reserve level (typically 3-6 months of operating expenses for nonprofits), and reporting reserve fund status to members regularly. Inadequate reserves can lead to special assessments, deferred maintenance, and financial instability.', category: 'financial', relatedTerms: ['annual-budget', 'assessment', 'hoa-dues', 'financial-audit'], faqQuestions: [{ question: 'How much should an organization have in reserves?', answer: 'For nonprofits and clubs, the general recommendation is 3-6 months of operating expenses. For HOAs, a reserve study determines the specific amount needed based on the replacement cost and remaining useful life of common elements.' }], keywords: ['reserve fund', 'operating reserves', 'nonprofit reserves', 'HOA reserve fund'] },
]

// ── communication (25 entries, alphabetical) ──────────────────────────────
const communication: GlossaryEntry[] = [
  { slug: 'ab-testing', term: 'A/B Testing', definition: 'A method of comparing two versions of an email, webpage, or other communication to determine which performs better. One variable is changed while everything else stays the same to isolate the impact.', extendedDefinition: 'A/B testing (also called split testing) is a data-driven approach to improving communications by testing two variations against each other. In the context of member communications, common elements to test include email subject lines (the most frequently tested element), call-to-action buttons (text, color, placement), email content and layout, send times and days, personalization approaches, and landing page designs. To conduct a valid A/B test, you need a large enough sample size to reach statistical significance, a clear hypothesis about what you expect to happen, only one variable changed between versions, random assignment of recipients to each version, and a defined success metric (open rate, click rate, conversion rate). Many email marketing platforms include built-in A/B testing features that automatically send the winning version to the remaining audience.', category: 'communication', relatedTerms: ['email-automation', 'open-rate', 'click-through-rate', 'drip-campaign'], faqQuestions: [{ question: 'What is the most impactful element to A/B test in emails?', answer: 'Subject lines typically have the biggest impact on email performance because they determine whether the email gets opened. After subject lines, test call-to-action buttons, send times, and content length.' }], keywords: ['A/B testing', 'split testing', 'email A/B test', 'A/B testing emails'] },
  { slug: 'bounce-rate', term: 'Bounce Rate (Email)', definition: 'The percentage of sent emails that could not be delivered to the recipient\'s inbox. A high bounce rate damages sender reputation and can cause future emails to be filtered as spam.', extendedDefinition: 'Email bounce rate measures the percentage of emails that are returned as undeliverable. There are two types: hard bounces (permanent delivery failures caused by invalid email addresses, closed accounts, or blocked domains) and soft bounces (temporary issues like full inboxes, server downtime, or messages that are too large). A healthy bounce rate is below 2%. Hard bounces should be removed from your list immediately, while soft bounces can be retried a few times before removal. High bounce rates can damage your sender reputation with email service providers, causing more of your legitimate emails to be filtered as spam. To maintain a low bounce rate, regularly clean your email list, use double opt-in for new subscribers, remove inactive addresses after a defined period, and validate email addresses at the point of collection. Many email platforms automatically handle bounces by removing hard bounces and suppressing persistent soft bounces.', category: 'communication', relatedTerms: ['open-rate', 'email-automation', 'email-deliverability', 'unsubscribe-rate'], faqQuestions: [{ question: 'What is a good email bounce rate?', answer: 'A healthy bounce rate is below 2%. If your bounce rate exceeds 5%, you likely have list quality issues that need immediate attention to protect your sender reputation.' }], keywords: ['email bounce rate', 'hard bounce', 'soft bounce', 'reduce email bounces'] },
  { slug: 'click-through-rate', term: 'Click-Through Rate (CTR)', definition: 'The percentage of email recipients who click on one or more links within an email. CTR indicates how engaging and relevant the email content is to the audience.', extendedDefinition: 'Click-through rate is calculated by dividing the number of unique clicks by the number of delivered emails and multiplying by 100. For membership organizations, the average CTR for association emails is approximately 2-4%. CTR is a more meaningful engagement metric than open rate because it indicates that the recipient not only opened the email but found the content compelling enough to take action. To improve CTR, make links and buttons visually prominent, use clear and action-oriented call-to-action text, ensure content is relevant to the specific audience segment, place the most important link above the fold, limit the number of competing links and calls to action, and use buttons rather than text links for primary actions. Tracking which links are clicked most frequently provides insights into what content your members find most valuable.', category: 'communication', relatedTerms: ['open-rate', 'ab-testing', 'email-automation', 'drip-campaign'], faqQuestions: [{ question: 'What is a good click-through rate for organization emails?', answer: 'For membership organizations and associations, a CTR of 2-4% is typical. Highly targeted, personalized emails to engaged segments can achieve 5-10% or higher.' }], keywords: ['click-through rate', 'CTR', 'email click rate', 'improve email CTR'] },
  { slug: 'drip-campaign', term: 'Drip Campaign', definition: 'An automated series of emails sent on a predetermined schedule, triggered by a specific action or date. Drip campaigns nurture relationships by delivering relevant content over time.', extendedDefinition: 'A drip campaign (also called an automated email sequence or nurture campaign) is a series of pre-written emails that are automatically sent to contacts based on triggers or schedules. Common drip campaigns for membership organizations include new member onboarding sequences (welcome, orientation, resource highlights over the first 30-90 days), renewal reminder series (starting 60 days before expiration with increasing urgency), lapsed member re-engagement campaigns, event promotion sequences, and volunteer recruitment funnels. The term "drip" refers to the idea of slowly dripping information to nurture a relationship rather than overwhelming the recipient all at once. Each email in the sequence should have a single clear purpose and call to action, build on previous emails, and provide value independent of the other emails. Performance should be monitored at each step to identify where recipients drop off and optimize accordingly.', category: 'communication', relatedTerms: ['email-automation', 'ab-testing', 'open-rate', 'click-through-rate'], faqQuestions: [{ question: 'How many emails should be in a drip campaign?', answer: 'It depends on the purpose. A new member onboarding sequence might have 5-7 emails over 90 days. A renewal reminder series might have 3-5 emails over 60 days. Start with fewer emails and add more based on engagement data.' }], keywords: ['drip campaign', 'email drip campaign', 'automated email sequence', 'nurture campaign'] },
  { slug: 'email-automation', term: 'Email Automation', definition: 'The use of software to automatically send emails based on predefined triggers, schedules, or member behaviors. Automation saves time while ensuring consistent, timely communication.', extendedDefinition: 'Email automation allows organizations to send the right message to the right person at the right time without manual effort. Automated emails are triggered by specific events or conditions such as a new member joining (triggering a welcome series), a membership renewal date approaching (triggering reminder emails), an event registration (triggering confirmation and pre-event communications), a birthday or membership anniversary, inactivity for a specified period, and form submissions or resource downloads. Benefits of email automation include consistent communication that does not depend on staff availability, timely delivery of time-sensitive messages, personalization at scale, reduced administrative workload, and measurable results that can be optimized over time. When implementing automation, start with the highest-impact sequences (welcome emails and renewal reminders), then expand to other use cases. Monitor performance metrics regularly and update content to keep it fresh and relevant.', category: 'communication', relatedTerms: ['drip-campaign', 'ab-testing', 'newsletter', 'open-rate'], faqQuestions: [{ question: 'What are the most important email automations for a membership organization?', answer: 'Start with three: (1) a welcome series for new members, (2) renewal reminder emails before expiration, and (3) lapsed member re-engagement emails. These three sequences address the most critical points in the member lifecycle.' }], keywords: ['email automation', 'automated emails', 'email workflow automation', 'membership email automation'] },
  { slug: 'email-deliverability', term: 'Email Deliverability', definition: 'The ability of emails to reach recipients\' inboxes rather than being filtered into spam, junk, or promotional folders. Deliverability depends on sender reputation, content, and technical configuration.', extendedDefinition: 'Email deliverability is the measure of how successfully your emails reach the intended recipient\'s inbox. Even if an email is technically delivered (not bounced), it may end up in spam or junk folders where it will never be seen. Key factors affecting deliverability include sender reputation (based on bounce rates, spam complaints, and engagement metrics), authentication protocols (SPF, DKIM, and DMARC records configured on your domain), email content (avoiding spam trigger words, maintaining a good text-to-image ratio), list hygiene (regularly removing inactive and invalid addresses), sending patterns (consistent volume and frequency), and engagement rates (emails that are opened and clicked improve future deliverability). Organizations should monitor their deliverability using tools provided by their email service provider and take corrective action when rates decline. Maintaining a clean list and good sending practices is essential for ensuring members receive important communications.', category: 'communication', relatedTerms: ['bounce-rate', 'open-rate', 'email-automation', 'unsubscribe-rate'], faqQuestions: [{ question: 'How can an organization improve email deliverability?', answer: 'Configure SPF, DKIM, and DMARC authentication, maintain list hygiene, keep bounce rates below 2%, use a consistent sending domain, avoid spammy language, send regularly to engaged subscribers, and make unsubscribing easy to reduce spam complaints.' }], keywords: ['email deliverability', 'inbox delivery rate', 'improve email deliverability', 'email spam filter'] },
  { slug: 'email-segmentation', term: 'Email Segmentation', definition: 'The practice of dividing an email list into targeted groups based on shared characteristics so that different groups receive different, more relevant messages.', extendedDefinition: 'Email segmentation is the foundation of effective email marketing for membership organizations. Instead of sending every email to the entire list, segmentation allows you to target specific groups with content tailored to their interests, needs, and behaviors. Common segmentation criteria include membership tier or type, engagement level, geographic location, interests and preferences, event attendance history, tenure with the organization, communication preferences, and demographic data. Segmented emails consistently outperform unsegmented emails across all metrics: open rates are 14% higher, click rates are 65% higher, and unsubscribe rates are 9% lower compared to non-segmented campaigns. Start with simple segments (new vs. established members, active vs. inactive) and refine over time as you collect more data. The quality of segmentation depends directly on the quality of your member data.', category: 'communication', relatedTerms: ['member-segmentation', 'email-automation', 'drip-campaign', 'ab-testing'], faqQuestions: [{ question: 'What are the most effective email segments for a membership organization?', answer: 'The highest-impact segments are new members (first 90 days), at-risk members (low engagement or approaching renewal), highly engaged members (potential volunteers or donors), and geographic segments for local events.' }], keywords: ['email segmentation', 'email list segmentation', 'segment email list', 'targeted email'] },
  { slug: 'mass-communication', term: 'Mass Communication', definition: 'The sending of one message to a large group of members, such as announcements, newsletters, or emergency updates.', extendedDefinition: 'Mass communication means sending one update to all members or to a large group. Use it for club-wide news, urgent updates, policy changes, votes, and major events. Keep the subject line clear. Get to the point fast. Use one main call to action. Make the email easy to read on a phone. Follow email rules like CAN-SPAM and GDPR. Include an easy way to unsubscribe. Too many mass emails can make members tune out. For urgent updates, pair email with a push alert or phone call.', category: 'communication', relatedTerms: ['newsletter', 'email-automation', 'email-segmentation', 'push-notification'], faqQuestions: [{ question: 'How often should an organization send mass emails?', answer: 'Most organizations should limit mass emails (sent to the entire membership) to 2-4 times per month. More frequent targeted or segmented emails are fine because they are more relevant to recipients.' }], keywords: ['mass communication', 'bulk email', 'mass email', 'organization announcement'] },
  { slug: 'multi-channel-communication', term: 'Multi-Channel Communication', definition: 'The plan for reaching members in more than one place, such as email, push alerts, social media, and in-app messages.', extendedDefinition: 'Multi-channel communication means using more than one channel to reach members. Common channels include email, push notifications, social media, in-app messages, direct mail, and phone calls. Each channel has a job. Email works well for details. Push alerts work well for fast updates. Social media helps build community. Phone calls help with personal follow-up. A good plan sends the same core message without flooding members. It also lets members set their preferences.', category: 'communication', relatedTerms: ['email-automation', 'push-notification', 'newsletter'], faqQuestions: [{ question: 'Which communication channels are most effective for membership organizations?', answer: 'Use email for detailed updates. Use push notifications for fast alerts. Use social media for community posts. Use phone calls when the message needs a personal touch.' }], keywords: ['multi-channel communication', 'omnichannel communication', 'member communication channels', 'communication strategy'] },
  { slug: 'newsletter', term: 'Newsletter', definition: 'A regularly distributed publication sent to members containing organizational news, upcoming events, articles, and other relevant content. Newsletters keep members informed and engaged between meetings.', extendedDefinition: 'A newsletter is a periodic communication (typically monthly or quarterly) that provides members with a curated mix of organizational news, upcoming events, member spotlights, educational content, and calls to action. Newsletters serve multiple purposes: keeping members informed about organizational activities, reinforcing the value of membership, driving attendance at events, recognizing member achievements, and maintaining regular contact between meetings. Effective newsletters have a consistent schedule and format, lead with the most important or interesting content, include a mix of informational and actionable content, feature member stories and achievements, are scannable with clear headings and short sections, include clear calls to action, and are optimized for mobile reading. Digital newsletters have largely replaced print versions due to lower cost, faster delivery, and the ability to track engagement metrics like open rates and click rates.', category: 'communication', relatedTerms: ['email-automation', 'open-rate', 'click-through-rate', 'mass-communication'], faqQuestions: [{ question: 'How often should an organization send a newsletter?', answer: 'Monthly is the most common frequency. Quarterly newsletters risk losing member attention between issues. Weekly can be too frequent unless the content is highly valuable. Choose a frequency you can maintain consistently.' }], keywords: ['newsletter', 'member newsletter', 'organization newsletter', 'email newsletter'] },
  { slug: 'open-rate', term: 'Open Rate', definition: 'The percentage of delivered emails that were opened by recipients. Open rate is a key metric for evaluating the effectiveness of email subject lines and sender reputation.', extendedDefinition: 'Open rate is calculated by dividing the number of unique opens by the number of delivered emails. For membership organizations, average open rates typically range from 20-30%, though highly engaged audiences can achieve 40-50% or higher. Open rates are influenced by the subject line (the single biggest factor), sender name and reputation, send time and day, list quality and engagement, preview text, and historical sending patterns. It is important to note that open rate tracking has become less reliable since Apple\'s Mail Privacy Protection (introduced in iOS 15) pre-loads tracking pixels, which inflates open rates for Apple Mail users. Despite this limitation, open rates remain a useful directional metric when compared over time and across campaigns. To improve open rates, write compelling subject lines, send at optimal times for your audience, maintain a clean list, and use a recognizable sender name.', category: 'communication', relatedTerms: ['click-through-rate', 'bounce-rate', 'ab-testing', 'email-deliverability'], faqQuestions: [{ question: 'What is a good email open rate for a membership organization?', answer: 'The average open rate for associations is 20-30%. Highly engaged member lists can achieve 35-50%. Note that Apple Mail Privacy Protection may inflate open rates, so use CTR as a more reliable engagement indicator.' }], keywords: ['email open rate', 'open rate', 'improve email open rate', 'average email open rate'] },
  { slug: 'push-notification', term: 'Push Notification', definition: 'A message from a mobile app or website that appears on a member\'s device. Push notifications are used for reminders and fast updates.', extendedDefinition: 'Push notifications appear on a phone or web browser even when the app is closed. Clubs can use them for event reminders, last-minute changes, dues reminders, important news, event updates, and new resources. Push alerts are easy to notice because they show on the device screen. Use them with care. Too many alerts can make members turn them off. Good push alerts are short, useful, and sent at a good time. Members should be able to choose what alerts they get.', category: 'communication', relatedTerms: ['multi-channel-communication', 'email-automation', 'mobile-app'], faqQuestions: [{ question: 'How often should push notifications be sent?', answer: 'Limit push notifications to 2-5 per week for engaged users. Every notification should provide clear, immediate value. Too many notifications cause users to disable them entirely, losing the channel permanently.' }], keywords: ['push notification', 'push notifications', 'mobile push notification', 'app notification'] },
  { slug: 'unsubscribe-rate', term: 'Unsubscribe Rate', definition: 'The percentage of email recipients who opt out of future emails after receiving a message. A high unsubscribe rate indicates that content is not relevant, too frequent, or not meeting member expectations.', extendedDefinition: 'Unsubscribe rate is calculated by dividing the number of unsubscribes by the number of delivered emails. A healthy unsubscribe rate for membership organizations is below 0.5% per email. Rates above 1% indicate a significant problem that needs attention. While some unsubscription is normal (people change interests, leave the area, or adjust their email habits), consistently high rates suggest issues with content relevance, sending frequency, or audience targeting. To minimize unsubscribes, segment your audience and send relevant content, maintain a consistent and reasonable sending frequency, set clear expectations about what subscribers will receive, make it easy to adjust communication preferences (rather than just unsubscribe completely), and provide valuable content in every email. Under CAN-SPAM regulations, unsubscribe requests must be honored within 10 business days, and the unsubscribe mechanism must be clearly visible in every commercial email.', category: 'communication', relatedTerms: ['bounce-rate', 'open-rate', 'email-deliverability', 'email-segmentation'], faqQuestions: [{ question: 'What is a normal unsubscribe rate?', answer: 'For membership organizations, a healthy unsubscribe rate is below 0.5% per email send. Rates above 1% per email warrant investigation into content relevance, sending frequency, and audience targeting.' }], keywords: ['unsubscribe rate', 'email unsubscribe rate', 'reduce email unsubscribes', 'email opt-out rate'] },
]

// ── technology (25 entries, alphabetical) ─────────────────────────────────
const technology: GlossaryEntry[] = [
  { slug: 'api-integration', term: 'API Integration', definition: 'A connection between two software systems that allows them to share data and functionality automatically. API integrations eliminate manual data entry and keep information synchronized across platforms.', extendedDefinition: 'An API (Application Programming Interface) integration connects two or more software systems so they can exchange data automatically. For membership organizations, common integrations include connecting member management software with email marketing platforms (syncing contact lists and engagement data), payment processors (processing dues and event payments), accounting software (synchronizing financial data), event management tools (sharing registration and attendance data), website or CMS (displaying member directories, event calendars), and communication platforms (triggering automated messages). Integrations save time by eliminating manual data transfer between systems, reduce errors from duplicate data entry, and enable more sophisticated automation workflows. When evaluating software for your organization, check what integrations are available natively or through integration platforms like Zapier. Well-integrated systems create a seamless experience for both administrators and members.', category: 'technology', relatedTerms: ['association-management-system', 'crm', 'zapier-integration', 'payment-gateway'], faqQuestions: [{ question: 'What is an API?', answer: 'An API (Application Programming Interface) is a set of rules that allows different software systems to communicate with each other. It defines how one system can request data or actions from another, enabling automatic data sharing and functionality between platforms.' }], keywords: ['API integration', 'software integration', 'API meaning', 'API integration examples'] },
  { slug: 'association-management-system', term: 'Association Management System (AMS)', definition: 'A comprehensive software platform designed specifically for managing membership organizations, combining member database, dues processing, event management, and communications into one system.', extendedDefinition: 'An Association Management System (AMS) is an all-in-one software solution built for the unique needs of membership organizations, trade associations, and professional societies. Unlike generic CRM systems, an AMS is purpose-built to handle the full lifecycle of membership management. Core AMS features include member database with custom fields, automated dues billing and payment processing, event registration and management, committee and volunteer tracking, communication tools (email, newsletters), online member portal with self-service capabilities, reporting and analytics, and content management for member resources. When evaluating AMS platforms, organizations should consider ease of use, scalability, integration capabilities, mobile accessibility, customer support, implementation timeline, and total cost of ownership. The AMS market has evolved significantly, with cloud-based solutions replacing traditional installed software, making modern systems more accessible and affordable for organizations of all sizes.', category: 'technology', relatedTerms: ['crm', 'member-database', 'api-integration', 'member-portal'], faqQuestions: [{ question: 'What is the difference between an AMS and a CRM?', answer: 'An AMS is purpose-built for membership organizations and includes features like dues processing, member portals, and committee tracking. A CRM (Customer Relationship Management) is a general-purpose tool for managing contacts and sales relationships. An AMS typically includes CRM functionality but adds membership-specific features.' }], keywords: ['association management system', 'AMS software', 'membership management software', 'AMS vs CRM'] },
  { slug: 'cloud-based-software', term: 'Cloud-Based Software', definition: 'Software that runs on remote servers accessed through the internet rather than installed on local computers. Cloud-based solutions offer automatic updates, remote access, and reduced IT maintenance.', extendedDefinition: 'Cloud-based software (also called Software as a Service or SaaS) is hosted on the provider\'s servers and accessed by users through a web browser or mobile app. For membership organizations, cloud-based solutions have largely replaced locally installed software because they offer several advantages: access from any device with an internet connection, automatic software updates and security patches, no need for dedicated IT staff or server hardware, scalable pricing that grows with the organization, automatic data backup and disaster recovery, and easier collaboration among multiple administrators. Common cloud-based tools for membership organizations include member management platforms, email marketing services, accounting software, file storage and collaboration, video conferencing, and project management. When choosing cloud-based solutions, consider data security and privacy compliance, uptime and reliability guarantees, data portability (can you export your data if you switch?), and the vendor\'s financial stability and track record.', category: 'technology', relatedTerms: ['association-management-system', 'api-integration', 'single-sign-on', 'data-security'], faqQuestions: [{ question: 'Is cloud-based software safe for storing member data?', answer: 'Reputable cloud providers invest heavily in security, often providing better protection than organizations can achieve on their own. Look for SOC 2 compliance, data encryption, regular security audits, and compliance with privacy regulations like GDPR.' }], keywords: ['cloud-based software', 'SaaS', 'cloud software', 'software as a service'] },
  { slug: 'crm', term: 'CRM (Customer Relationship Management)', definition: 'Software that manages an organization\'s interactions with current and potential members, tracking communications, engagement, and relationships to improve retention and growth.', extendedDefinition: 'A CRM (Customer Relationship Management) system is software designed to manage and analyze interactions with contacts and stakeholders. While CRMs were originally developed for sales teams, they have been adapted for membership organizations to track the full member relationship lifecycle. A CRM for membership use tracks contact information and communication history, member engagement and participation, event attendance and interests, volunteer activities and committee involvement, donation and payment history, and communication preferences. The CRM serves as a centralized knowledge base so that any staff member or volunteer leader can understand a member\'s full history with the organization. While many membership organizations use purpose-built AMS platforms that include CRM functionality, some use general CRM platforms like Salesforce (with the Nonprofit Success Pack), HubSpot, or specialized nonprofit CRMs. The key benefit is having a complete view of each member\'s relationship with the organization.', category: 'technology', relatedTerms: ['association-management-system', 'member-database', 'api-integration', 'member-engagement'], faqQuestions: [{ question: 'Does a small club need a CRM?', answer: 'Small clubs (under 50 members) may manage with a spreadsheet. As the organization grows, a CRM or member management platform becomes valuable for tracking interactions, automating communications, and preventing important details from being lost when leadership changes.' }], keywords: ['CRM', 'customer relationship management', 'CRM for nonprofits', 'membership CRM'] },
  { slug: 'data-security', term: 'Data Security', definition: 'The practices, technologies, and policies used to protect member data from unauthorized access, breaches, and loss. Data security is both a legal requirement and a trust obligation to members.', extendedDefinition: 'Data security for membership organizations involves protecting sensitive member information including personal details, payment data, communications, and organizational records. Key components of a data security program include access controls (limiting who can view and modify member data based on their role), encryption (protecting data both in transit and at rest), authentication (requiring strong passwords, two-factor authentication), regular backups (ensuring data can be recovered in case of loss), security training (educating staff and volunteers about threats like phishing), incident response plan (knowing what to do if a breach occurs), and compliance with applicable regulations (GDPR, CCPA, PCI DSS for payment data). Organizations should conduct regular security assessments, keep software updated, and have clear data retention and disposal policies. When selecting technology vendors, evaluate their security certifications, data handling practices, and breach notification procedures.', category: 'technology', relatedTerms: ['single-sign-on', 'cloud-based-software', 'member-database', 'payment-gateway'], faqQuestions: [{ question: 'What are the biggest data security risks for membership organizations?', answer: 'The biggest risks are phishing attacks targeting staff and volunteers, weak passwords, unauthorized access by former leaders, unsecured spreadsheets with member data, and outdated software with known vulnerabilities.' }], keywords: ['data security', 'member data protection', 'nonprofit data security', 'data breach prevention'] },
  { slug: 'digital-membership-card', term: 'Digital Membership Card', definition: 'A virtual version of a membership card stored on a member\'s smartphone, typically accessible through a mobile app or digital wallet. Digital cards are convenient, always available, and easy to update.', extendedDefinition: 'Digital membership cards replace traditional plastic or paper cards with virtual versions stored on members\' smartphones. They can be accessed through the organization\'s mobile app, a mobile wallet (Apple Wallet or Google Wallet), or via a unique URL. Digital cards offer several advantages over physical cards: they cannot be forgotten at home, they can be updated automatically when membership status changes, they can include dynamic information like QR codes for event check-in, they eliminate printing and mailing costs, they can be shared easily for verification purposes, and they reduce environmental impact. Features commonly included on digital cards include member name and photo, membership tier and expiration date, a scannable QR code or barcode for verification, and the organization\'s contact information. Organizations transitioning from physical to digital cards should offer both options during the transition period to accommodate members who prefer traditional cards.', category: 'technology', relatedTerms: ['mobile-app', 'member-portal', 'qr-code', 'member-database'], faqQuestions: [{ question: 'How do digital membership cards work?', answer: 'Digital cards are typically accessed through a mobile app or added to Apple Wallet or Google Wallet. They display member information and may include a QR code for verification at events or for accessing member benefits. They update automatically when membership status changes.' }], keywords: ['digital membership card', 'virtual membership card', 'mobile membership card', 'digital member ID'] },
  { slug: 'dues-automation', term: 'Dues Automation', definition: 'The use of software to automatically handle the entire dues collection cycle, including invoicing, payment processing, reminders, receipt generation, and membership status updates.', extendedDefinition: 'Dues automation streamlines the entire membership payment process from start to finish, eliminating manual tasks and reducing the risk of errors or missed follow-ups. A fully automated dues system handles automatic invoicing at renewal time, multiple payment method options (credit card, ACH, online portal), recurring payment processing for auto-pay members, automated reminder emails for upcoming and overdue payments, automatic receipt and confirmation generation, membership status updates based on payment status, grace period management, failed payment retry and notification, and reporting on collection rates and outstanding balances. Organizations that implement dues automation typically see improved collection rates, reduced administrative time, faster payment processing, and better member experience. The system should integrate with the member database to automatically update membership status when payments are received or lapse, ensuring that member benefits and access are accurately maintained.', category: 'technology', relatedTerms: ['dues-collection', 'recurring-payment', 'email-automation', 'association-management-system'], faqQuestions: [{ question: 'How much time does dues automation save?', answer: 'Organizations that automate dues collection typically reduce administrative time by 60-80% compared to manual processes. The savings increase as membership grows, since the automated system handles any volume without additional effort.' }], keywords: ['dues automation', 'automate dues collection', 'membership billing automation', 'automated membership renewal'] },
  { slug: 'mobile-app', term: 'Mobile App', definition: 'A software application designed for smartphones and tablets that gives members on-the-go access to organizational features like event registration, dues payment, member directory, and notifications.', extendedDefinition: 'A mobile app provides members with convenient, always-available access to organizational services and information. For membership organizations, mobile apps typically include member directory and networking, event calendar and registration, dues payment and billing, push notifications for announcements and reminders, digital membership card, document and resource library, real-time chat and messaging, QR code check-in for events, and volunteer sign-up and hour tracking. Mobile apps increase member engagement by making interaction with the organization frictionless - members can RSVP to events, pay dues, check the directory, and receive updates from anywhere. When deciding between a custom app and a platform-provided app, consider development and maintenance costs, feature requirements, the percentage of your membership likely to install and use an app, and whether a mobile-optimized website might serve the same purpose at lower cost.', category: 'technology', relatedTerms: ['push-notification', 'digital-membership-card', 'member-portal', 'qr-code'], faqQuestions: [{ question: 'Does every membership organization need a mobile app?', answer: 'Not necessarily. Organizations with highly engaged members who interact frequently benefit most from apps. For others, a mobile-optimized website may be sufficient. Consider whether your members would regularly use an app before investing in one.' }], keywords: ['membership mobile app', 'club mobile app', 'organization mobile app', 'member app'] },
  { slug: 'online-voting', term: 'Online Voting', definition: 'A system that allows members to cast votes electronically via a website or app instead of in person. Online voting increases participation by removing geographic and scheduling barriers.', extendedDefinition: 'Online voting enables organizations to conduct elections, approve bylaws changes, and make decisions without requiring all members to be physically present. This is particularly valuable for organizations with geographically dispersed members, those with members who have difficulty attending in-person meetings, and situations requiring broad member input. Online voting platforms typically provide secure authentication to verify voter identity, anonymous ballots when required, real-time vote tallying, audit trails for transparency, voter eligibility verification, deadline management, and results reporting. Before implementing online voting, organizations must verify that their bylaws permit electronic voting and amend them if necessary. Security considerations include preventing duplicate voting, protecting voter anonymity when appropriate, ensuring system integrity, and maintaining verifiable records. Many organizations use hybrid approaches, allowing members to vote either in person or online to maximize participation.', category: 'technology', relatedTerms: ['proxy-voting', 'quorum', 'bylaws', 'member-portal'], faqQuestions: [{ question: 'Do bylaws need to be changed to allow online voting?', answer: 'Usually yes. Most bylaws specify how votes are conducted, and many default to in-person voting. Review your bylaws and amend them to explicitly authorize electronic voting before implementing it.' }], keywords: ['online voting', 'electronic voting', 'online election', 'membership online vote'] },
  { slug: 'single-sign-on', term: 'Single Sign-On (SSO)', definition: 'An authentication method that allows members to log in once and access multiple connected applications without entering separate credentials for each one.', extendedDefinition: 'Single Sign-On (SSO) simplifies the member experience by requiring only one set of login credentials to access multiple organizational systems. Instead of remembering separate usernames and passwords for the member portal, event registration, learning management system, online community, and other platforms, members log in once and are automatically authenticated across all connected applications. SSO improves security by reducing the number of passwords members need to manage (fewer passwords means fewer weak or reused passwords), enables centralized access management (when a member\'s status changes, access can be updated in one place), and reduces support requests for password resets. Common SSO protocols include SAML, OAuth 2.0, and OpenID Connect. For membership organizations, SSO is particularly valuable when using multiple software platforms that members need to access, creating a seamless experience that reduces friction and increases engagement.', category: 'technology', relatedTerms: ['data-security', 'member-portal', 'api-integration', 'cloud-based-software'], faqQuestions: [{ question: 'What are the benefits of SSO for a membership organization?', answer: 'SSO reduces password fatigue, improves security, decreases support requests, and creates a seamless experience when members use multiple organizational platforms. It also simplifies access management when memberships change.' }], keywords: ['single sign-on', 'SSO', 'SSO meaning', 'single sign on membership'] },
  { slug: 'zapier-integration', term: 'Zapier Integration', definition: 'A connection made through the Zapier automation platform that links two or more applications without requiring custom code. Zapier enables organizations to automate workflows between their software tools.', extendedDefinition: 'Zapier is a no-code automation platform that connects thousands of applications through automated workflows called "Zaps." For membership organizations, Zapier can automate repetitive tasks by connecting their various tools. Common Zap examples include adding new event registrations to a Google Sheet automatically, sending a Slack notification when a new member joins, creating a follow-up task when a member\'s dues are overdue, syncing new contacts between the CRM and email marketing platform, posting to social media when a new blog post is published, and creating calendar events from form submissions. Each Zap consists of a trigger (an event in one app that starts the workflow) and one or more actions (tasks performed in other apps). Zapier is valuable for organizations that use multiple platforms that do not have native integrations, offering a way to connect systems without custom development. Similar platforms include Make (formerly Integromat), n8n, and Microsoft Power Automate.', category: 'technology', relatedTerms: ['api-integration', 'email-automation', 'association-management-system', 'cloud-based-software'], faqQuestions: [{ question: 'What can Zapier automate for a membership organization?', answer: 'Common automations include syncing new members to email lists, sending notifications for new registrations, creating tasks for follow-ups, updating spreadsheets from form submissions, and posting social media updates when new content is published.' }], keywords: ['Zapier', 'Zapier integration', 'Zapier automation', 'no-code automation'] },
]

// ── combined + sorted ────────────────────────────────────────────────────
export const GLOSSARY_ENTRIES: GlossaryEntry[] = [
  ...governance,
  ...nonprofit,
  ...events,
  ...volunteer,
  ...membership,
  ...financial,
  ...communication,
  ...technology,
]

// ── helper functions ─────────────────────────────────────────────────────

export function getGlossaryEntryBySlug(slug: string): GlossaryEntry | undefined {
  return GLOSSARY_ENTRIES.find((e) => e.slug === slug)
}

export function getAllGlossarySlugs(): string[] {
  return GLOSSARY_ENTRIES.map((e) => e.slug)
}

export function getGlossaryEntriesByCategory(category: GlossaryCategory): GlossaryEntry[] {
  return GLOSSARY_ENTRIES.filter((e) => e.category === category)
}
